import type { TrainingCard } from '../types';

export const cards: TrainingCard[] = [
  { id: "pm-01", category: "01", group: "product", level: "foundation", mode: "recall", frontQuestion: "Which metric tells you what share of new users reaches the first meaningful value milestone?", frontScenario: "A project-management app gets thousands of sign-ups, but the team cares whether newcomers actually create and share their first project.", answer: "Activation Rate", backInfo: "The percentage of new users who complete the product's defined activation event. The activation event must represent meaningful value, not just account creation.", formula: "activated new users / eligible new users × 100." },
  { id: "pm-02", category: "01", group: "product", level: "foundation", mode: "recall", frontQuestion: "Which metric tells you what share of a user cohort comes back and keeps using the product after a chosen period?", frontScenario: "A fitness app wants to know how many people who started this month are still active 30 days later.", answer: "Retention Rate", backInfo: "Measures continued use over time for a defined cohort and return behavior. Always define the time window and what counts as “retained.”", formula: "retained users / users in the starting cohort × 100." },
  { id: "pm-03", category: "01", group: "product", level: "foundation", mode: "distinction", frontQuestion: "Which metric tells you what share of customers or users stopped using or paying during a period?", frontScenario: "A SaaS product has stable acquisition but the customer base is barely growing because many accounts cancel each month.", answer: "Churn Rate", backInfo: "Measures loss over a period. It can refer to users/customers or to revenue, so specify which one. Formula (customer churn): customers lost / customers at start of period × 100." },
  { id: "pm-04", category: "01", group: "product", level: "foundation", mode: "recall", frontQuestion: "Which metric tells you how many unique users are active on a typical day?", frontScenario: "A messaging product wants a daily view of how many distinct people actually use the service.", answer: "DAU — Daily Active Users", backInfo: "Number of unique users who perform the defined active behavior in a day. “Active” must be tied to meaningful product behavior, not automatically to any page load." },
  { id: "pm-05", category: "01", group: "product", level: "foundation", mode: "recall", frontQuestion: "Which metric tells you how many unique users are active within a week?", frontScenario: "A collaboration tool is used several times per week rather than every day, so daily activity alone looks artificially low.", answer: "WAU — Weekly Active Users", backInfo: "Number of unique users who meet the active-user definition during a rolling or calendar week. Useful for products with a weekly usage cadence." },
  { id: "pm-06", category: "01", group: "product", level: "foundation", mode: "recall", frontQuestion: "Which metric tells you how many unique users are active within a month?", frontScenario: "A tax or finance tool may be valuable even if people do not open it every day. The team needs a broader active-user measure.", answer: "MAU — Monthly Active Users", backInfo: "Number of unique users who meet the product's active-user definition during a month. Useful as a broad measure of active reach, but it does not show depth of engagement." },
  { id: "pm-07", category: "01", group: "product", level: "practice", mode: "interpretation", frontQuestion: "Which ratio helps you estimate how frequently monthly users return on a daily basis?", frontScenario: "Two apps both have 100k MAU, but one is used almost every day while the other is opened once a month.", answer: "DAU/MAU Stickiness", backInfo: "A frequency proxy showing the share of monthly active users who are active on a typical day. Compare only products with similar natural usage cadence.", formula: "DAU / MAU × 100." },
  { id: "pm-08", category: "01", group: "product", level: "practice", mode: "recall", frontQuestion: "Which metric tells you what share of relevant users has tried or used a specific feature?", frontScenario: "A team launches collaborative comments and wants to know whether existing active users are actually discovering and using them.", answer: "Feature Adoption Rate", backInfo: "Share of eligible or active users who use a feature during a defined period. Define the denominator explicitly.", formula: "feature users / defined eligible population × 100." },
  { id: "pm-09", category: "01", group: "product", level: "practice", mode: "distinction", frontQuestion: "Which concept describes how many different users use a feature rather than how often each user uses it?", frontScenario: "A dashboard is used by 70% of customers, but most open it only once. The team wants to separate reach from frequency.", answer: "Breadth of Adoption", backInfo: "Breadth describes how widely a feature is used across the relevant user base. It complements depth and frequency; high breadth does not necessarily mean strong engagement." },
  { id: "pm-10", category: "01", group: "product", level: "practice", mode: "distinction", frontQuestion: "Which concept describes how intensively people use a feature once they have adopted it?", frontScenario: "Only a small group uses an advanced editor, but those users create dozens of items every week.", answer: "Depth of Engagement", backInfo: "Depth measures the amount or richness of use among engaged users, such as actions, items created, or meaningful steps completed. It should be tied to value, not raw clicks." },
  { id: "pm-11", category: "01", group: "product", level: "practice", mode: "recall", frontQuestion: "Which metric tells you how often an active user performs a meaningful action in a period?", frontScenario: "A calendar feature is widely adopted, but the team needs to know whether people use it once or repeatedly.", answer: "Usage Frequency", backInfo: "Measures repeated use of a product or feature per user over a defined interval. Useful alongside adoption because “used once” and “used habitually” are different states." },
  { id: "pm-12", category: "01", group: "product", level: "practice", mode: "application", frontQuestion: "Which metric tells you how long it takes a new user to reach the activation milestone?", frontScenario: "People eventually discover the value of a workflow tool, but some need three sessions before creating their first useful automation.", answer: "Time to Activate", backInfo: "Time between acquisition/sign-up and the defined activation event. Shorter is often better when the activation event truly represents value; do not optimize speed toward a meaningless event." },
  { id: "pm-13", category: "01", group: "product", level: "practice", mode: "application", frontQuestion: "Which concept focuses on how quickly a customer experiences meaningful value, not merely completes onboarding?", frontScenario: "An enterprise buyer finishes setup on day one but sees the first successful business outcome two weeks later.", answer: "Time to Value — TTV", backInfo: "Time required for a user/customer to realize meaningful product value. It may extend beyond onboarding or activation and is especially important in B2B and complex products." },
  { id: "pm-14", category: "01", group: "product", level: "foundation", mode: "recall", frontQuestion: "Which metric tells you what share of users completes a target action such as purchase, signup or upgrade?", frontScenario: "An e-commerce team wants to know what percentage of checkout visitors actually place an order.", answer: "Conversion Rate", backInfo: "Share of an eligible population that completes a defined target action. Always specify the funnel stage and denominator.", formula: "converters / eligible users or sessions × 100." },
  { id: "pm-15", category: "01", group: "product", level: "foundation", mode: "recall", frontQuestion: "Which metric tells you what share of users finishes a defined task or flow after starting it?", frontScenario: "Users begin identity verification, but the team wants to know how many reach the final confirmation screen.", answer: "Completion Rate", backInfo: "Percentage of starters who reach the defined completion point. Useful for onboarding, forms, setup and multi-step tasks.", formula: "completed flows / started flows × 100." },
  { id: "pm-16", category: "01", group: "product", level: "foundation", mode: "distinction", frontQuestion: "Which metric tells you what share of people leaves a flow before reaching the next required step?", frontScenario: "A checkout loses a large number of users between delivery details and payment.", answer: "Drop-off Rate", backInfo: "Share of users who fail to progress from a step or stage. It is usually examined step-by-step in a funnel to locate friction rather than treated as one universal product metric." },
  { id: "pm-17", category: "01", group: "product", level: "practice", mode: "recall", frontQuestion: "Which metric measures the share of users who return specifically after first using a feature?", frontScenario: "The team knows many people try AI summaries once and wants to know whether they come back to use that feature again.", answer: "Feature Retention", backInfo: "Measures continued use of a specific feature after initial use. It helps distinguish novelty-driven trials from durable feature value." },
  { id: "pm-18", category: "01", group: "product", level: "practice", mode: "interpretation", frontQuestion: "Which analysis groups users by a shared starting event or characteristic so their behavior can be compared over time?", frontScenario: "The team wants to compare retention for users who signed up in January versus February after an onboarding redesign.", answer: "Cohort Analysis", backInfo: "Groups users by a shared attribute or event and compares subsequent behavior. Cohorts help avoid mixing users with very different start dates or experiences." },
  { id: "pm-19", category: "01", group: "product", level: "advanced", mode: "interpretation", frontQuestion: "Which curve shows how the share of a cohort still returning changes as time passes?", frontScenario: "A social app sees a steep early decline but then a stable group continues using it for months.", answer: "Retention Curve", backInfo: "A time-series view of retained users in a cohort. The shape reveals early loss and whether retention eventually stabilizes; the relevant interval depends on natural product usage." },
  { id: "pm-20", category: "01", group: "product", level: "practice", mode: "distinction", frontQuestion: "Which metric focuses on customers who were inactive but became active again?", frontScenario: "A streaming app sends a win-back campaign and wants to track previously dormant users who return.", answer: "Reactivation Rate", backInfo: "Measures the share or number of previously inactive users who resume meaningful activity. Define the inactivity threshold and reactivation event before measuring it." },
  { id: "pm-21", category: "01", group: "product", level: "advanced", mode: "interpretation", frontQuestion: "Which lifecycle concept separates active users into new, current and previously inactive users who returned?", frontScenario: "MAU is flat, but the team needs to know whether stability comes from loyal current users or from constantly replacing lost users.", answer: "User Lifecycle Segmentation", backInfo: "Splits activity into lifecycle states such as new, current, dormant and resurrected/reactivated users. It explains the composition behind a single active-user total." },
  { id: "pm-22", category: "01", group: "product", level: "advanced", mode: "application", frontQuestion: "Which metric should represent the recurring user behavior that best captures the core value your product delivers?", frontScenario: "A marketplace could track page views, listings or successful transactions, but the team needs one value-centered metric to align product decisions.", answer: "North Star Metric", backInfo: "A durable metric representing delivered customer value and linked to sustainable business outcomes. It should be supported by input and guardrail metrics, not treated as the only number that matters." },
  { id: "gr-01", category: "02", group: "product", level: "foundation", mode: "recall", frontQuestion: "Which metric tells you the average cost of acquiring one paying customer?", frontScenario: "A startup spends on ads, content and sales and wants to know what each new customer effectively costs.", answer: "CAC — Customer Acquisition Cost", backInfo: "Average acquisition cost per new customer. Define which costs and period are included.", formula: "relevant sales + marketing acquisition costs / new customers acquired." },
  { id: "gr-02", category: "02", group: "product", level: "foundation", mode: "recall", frontQuestion: "Which metric estimates the economic value a customer generates across the whole relationship?", frontScenario: "A subscription business can spend more to acquire customers who typically remain and pay for several years.", answer: "Customer Lifetime Value — LTV/CLV", backInfo: "Estimated value generated by a customer over the relationship, often based on revenue or gross profit. The calculation varies by business model; state the method rather than treating one formula as universal." },
  { id: "gr-03", category: "02", group: "product", level: "practice", mode: "interpretation", frontQuestion: "Which ratio helps you judge whether customer acquisition economics are sustainable?", frontScenario: "Marketing can double sign-ups, but leadership needs to know whether the lifetime value generated justifies the acquisition cost.", answer: "LTV:CAC Ratio", backInfo: "Compares estimated customer lifetime value with acquisition cost. It is a directional unit-economics signal, not a universal benchmark; growth stage, margin and payback timing matter." },
  { id: "gr-04", category: "02", group: "product", level: "practice", mode: "recall", frontQuestion: "Which metric tells you how long it takes gross profit or contribution from a customer to recover acquisition cost?", frontScenario: "A B2B SaaS company spends heavily on sales and wants to know how many months pass before a new account pays back that investment.", answer: "CAC Payback Period", backInfo: "Time needed to recover CAC from the customer's recurring gross profit/contribution. Shorter payback generally reduces financing pressure, but acceptable ranges depend on the business." },
  { id: "gr-05", category: "02", group: "product", level: "foundation", mode: "recall", frontQuestion: "Which metric tells you predictable subscription revenue normalized to one month?", frontScenario: "A SaaS business has customers on different billing dates and wants a consistent view of recurring revenue.", answer: "MRR — Monthly Recurring Revenue", backInfo: "Recurring subscription revenue normalized to a month. Exclude one-off services and other non-recurring revenue when using MRR as a subscription metric." },
  { id: "gr-06", category: "02", group: "product", level: "foundation", mode: "recall", frontQuestion: "Which metric expresses recurring subscription revenue on an annualized basis?", frontScenario: "Leadership wants a simple annual run-rate view derived from recurring subscriptions.", answer: "ARR — Annual Recurring Revenue", backInfo: "Annualized recurring revenue, commonly derived from recurring contracts or MRR. It is not the same as total annual revenue when one-off revenue exists." },
  { id: "gr-07", category: "02", group: "product", level: "foundation", mode: "recall", frontQuestion: "Which metric tells you average revenue generated per user in a period?", frontScenario: "A consumer subscription app wants to compare monetization across countries with different plan mixes.", answer: "ARPU — Average Revenue per User", backInfo: "Average revenue per user over a defined period. Specify whether “user” means active, paying or total users.", formula: "revenue / relevant users." },
  { id: "gr-08", category: "02", group: "product", level: "practice", mode: "distinction", frontQuestion: "Which metric is more appropriate than ARPU when revenue is contracted and billed at the company/account level?", frontScenario: "An enterprise SaaS platform has thousands of seats but contracts with 200 customer organizations.", answer: "ARPA — Average Revenue per Account", backInfo: "Average revenue per customer account over a period. It is often more meaningful than per-user revenue in B2B products sold at account or workspace level." },
  { id: "gr-09", category: "02", group: "product", level: "foundation", mode: "recall", frontQuestion: "Which metric tells you the average value of an e-commerce transaction?", frontScenario: "A retailer's order count is stable, but the team wants to know whether customers are spending more per purchase.", answer: "AOV — Average Order Value", backInfo: "Average revenue per completed order. Useful for merchandising, bundling and checkout strategy.", formula: "order revenue / number of orders." },
  { id: "gr-10", category: "02", group: "product", level: "practice", mode: "recall", frontQuestion: "Which metric shows recurring revenue retained after cancellations, downgrades and expansions from the existing customer base?", frontScenario: "A SaaS company loses some accounts but remaining customers upgrade enough that existing-account revenue still grows.", answer: "NRR — Net Revenue Retention", backInfo: "Measures recurring revenue retained from an existing customer cohort including expansion, contraction and churn.", formula: "starting recurring revenue + expansion − contraction − churn / starting recurring revenue × 100." },
  { id: "gr-11", category: "02", group: "product", level: "practice", mode: "distinction", frontQuestion: "Which retention metric ignores upgrades and expansion so you can see how much recurring revenue survives losses alone?", frontScenario: "Expansion revenue is masking a serious downgrade and cancellation problem.", answer: "GRR — Gross Revenue Retention", backInfo: "Measures recurring revenue retained before expansion. It captures churn and contraction but not upsell, making underlying revenue loss easier to see." },
  { id: "gr-12", category: "02", group: "product", level: "practice", mode: "recall", frontQuestion: "Which metric tells you how much additional recurring revenue came from upgrades or add-ons among existing customers?", frontScenario: "A SaaS product launches paid add-ons and wants to separate that growth from new-logo acquisition.", answer: "Expansion Revenue", backInfo: "Additional revenue generated from existing customers through upgrades, additional seats, add-ons or increased usage. It is an important driver of NRR." },
  { id: "gr-13", category: "02", group: "product", level: "foundation", mode: "recall", frontQuestion: "Which metric tells you what percentage of revenue remains after direct cost of delivering the product or service?", frontScenario: "Two products have the same revenue, but one has far higher infrastructure and service-delivery costs.", answer: "Gross Margin", backInfo: "Revenue left after cost of goods/services sold. Useful for understanding economic efficiency before operating expenses.", formula: "(revenue − COGS) / revenue × 100." },
  { id: "gr-14", category: "02", group: "product", level: "practice", mode: "recall", frontQuestion: "Which metric estimates what remains from a sale after variable costs that scale with that sale?", frontScenario: "A marketplace needs to know whether each additional transaction contributes enough to cover fixed operating costs.", answer: "Contribution Margin", backInfo: "Revenue minus variable costs attributable to producing or serving that revenue. It is useful for unit economics and break-even decisions; definitions vary by business." },
  { id: "gr-15", category: "02", group: "product", level: "foundation", mode: "recall", frontQuestion: "Which metric tells you how much revenue an advertising campaign produces for each unit of ad spend?", frontScenario: "A growth team compares paid search with social ads and wants a revenue-based efficiency measure.", answer: "ROAS — Return on Ad Spend", backInfo: "Revenue attributed to advertising divided by ad spend. It does not include all business costs and depends heavily on attribution quality.", formula: "attributed revenue / ad spend." },
  { id: "gr-16", category: "02", group: "product", level: "foundation", mode: "recall", frontQuestion: "Which metric tells you the percentage of ad or link impressions that resulted in a click?", frontScenario: "A campaign is seen by millions of people, but the team wants to know whether the creative actually prompts visits.", answer: "CTR — Click-Through Rate", backInfo: "Share of impressions that produce clicks. High CTR does not guarantee high-quality traffic or downstream conversion.", formula: "clicks / impressions × 100." },
  { id: "gr-17", category: "02", group: "product", level: "practice", mode: "recall", frontQuestion: "Which metric measures how much value is exchanged through a marketplace before the platform takes its fee?", frontScenario: "A marketplace earns a commission, but first needs to know the total value of transactions completed between buyers and sellers.", answer: "GMV — Gross Merchandise Value", backInfo: "Total value of transactions facilitated over a period before fees, refunds or other deductions as defined by the business. It is not the marketplace's own revenue." },
  { id: "gr-18", category: "02", group: "product", level: "practice", mode: "distinction", frontQuestion: "Which metric tells you what share of marketplace transaction value the platform keeps as revenue?", frontScenario: "A marketplace processes €10M in sales but earns only the commission and service fees.", answer: "Take Rate", backInfo: "Percentage of transaction value captured by the platform as revenue. Definitions should specify which fees and transaction value are included.", formula: "platform revenue / relevant GMV × 100." },
  { id: "an-01", category: "03", group: "product", level: "foundation", mode: "recall", frontQuestion: "What is the basic analytics unit for a meaningful action a user performs?", frontScenario: "The team wants to record actions such as `project_created`, `checkout_started` and `invite_sent`.", answer: "Event", backInfo: "A named occurrence representing user or system behavior. Good events express meaningful actions and use a consistent naming convention." },
  { id: "an-02", category: "03", group: "product", level: "foundation", mode: "recall", frontQuestion: "What analytics data describes the context or attributes attached to an event?", frontScenario: "`purchase_completed` is useful, but the team also needs price, plan, device and payment method.", answer: "Event Property", backInfo: "Attribute attached to an event that adds context for filtering, grouping and analysis. Properties should have documented names, types and allowed values." },
  { id: "an-03", category: "03", group: "product", level: "foundation", mode: "distinction", frontQuestion: "What analytics data describes a person or account rather than one individual action?", frontScenario: "The team wants to segment behavior by plan type, region and customer role.", answer: "User Property", backInfo: "Persistent or changing attribute associated with a user, account or profile rather than a single event. Avoid storing sensitive data without a valid need and governance." },
  { id: "an-04", category: "03", group: "product", level: "foundation", mode: "recall", frontQuestion: "What artifact defines which events and properties must be captured and how they are named?", frontScenario: "Designers, PMs and engineers keep creating slightly different names for the same behaviors.", answer: "Tracking Plan", backInfo: "Shared specification for analytics events, properties, naming, triggers, owners and validation. It prevents inconsistent instrumentation from undermining analysis." },
  { id: "an-05", category: "03", group: "product", level: "practice", mode: "recall", frontQuestion: "What process adds the actual analytics events and properties to the product code or data pipeline?", frontScenario: "The team has agreed what to measure, but engineering still needs to make those behaviors observable.", answer: "Instrumentation", backInfo: "Implementation of data collection in the product and supporting systems. Good instrumentation is tested like other product functionality." },
  { id: "an-06", category: "03", group: "product", level: "foundation", mode: "recall", frontQuestion: "Which analysis shows how users progress through a predefined sequence of steps and where they leave?", frontScenario: "Many users add an item to cart, but far fewer complete checkout.", answer: "Funnel Analysis", backInfo: "Measures progression and conversion through ordered steps. It is best for known paths; not every real user journey is strictly linear." },
  { id: "an-07", category: "03", group: "product", level: "practice", mode: "recall", frontQuestion: "Which analysis reveals common sequences users actually take without forcing them into a predefined funnel?", frontScenario: "The team does not know what people do between signup and first value and wants to see real behavior paths.", answer: "Path Analysis", backInfo: "Explores observed event sequences before or after selected actions. Useful for discovering unexpected routes, loops and dead ends." },
  { id: "an-08", category: "03", group: "product", level: "foundation", mode: "recall", frontQuestion: "Which analysis divides users into groups so behavior can be compared by attributes or conditions?", frontScenario: "The team wants to compare activation for mobile vs desktop and free vs paid users.", answer: "Segmentation", backInfo: "Breaks metrics or behavior into meaningful groups. Segments help expose averages that hide important differences." },
  { id: "an-09", category: "03", group: "product", level: "practice", mode: "distinction", frontQuestion: "Which concept means a saved group of users defined by shared attributes or behavior?", frontScenario: "The team repeatedly analyzes users who invited a teammate within their first day.", answer: "Behavioral Cohort", backInfo: "A reusable group defined by shared behavior or characteristics. Behavioral cohorts can be compared for retention, conversion and other outcomes." },
  { id: "an-10", category: "03", group: "product", level: "practice", mode: "recall", frontQuestion: "What analytics view groups activity into visits or periods of continuous interaction?", frontScenario: "The team wants to understand how much users do during a typical visit, not only across a month.", answer: "Session", backInfo: "A grouping of user activity within a defined period or inactivity timeout. Session definitions vary by tool and may be less meaningful for always-on or multi-device products." },
  { id: "an-11", category: "03", group: "product", level: "advanced", mode: "application", frontQuestion: "What validation process checks that analytics events fire correctly with the right schema and values?", frontScenario: "A new release shipped, but dashboards suddenly show impossible conversion numbers.", answer: "Analytics QA", backInfo: "Verification of event triggers, identities, properties, types, duplication and environment behavior. It should happen before relying on new instrumentation for decisions." },
  { id: "an-12", category: "03", group: "product", level: "advanced", mode: "distinction", frontQuestion: "What problem occurs when the same real person is counted as separate anonymous and logged-in users?", frontScenario: "A person browses anonymously, signs up, then appears as two users in the funnel.", answer: "Identity Resolution", backInfo: "Process of linking anonymous, logged-in and cross-device identifiers to the same user/account where appropriate. Poor identity logic distorts funnels and retention." },
  { id: "an-13", category: "03", group: "product", level: "practice", mode: "recall", frontQuestion: "What analysis helps determine which marketing source or touchpoint receives credit for a conversion?", frontScenario: "A buyer sees an ad, reads an article, then later returns through search and purchases.", answer: "Attribution", backInfo: "Rules or models assigning conversion credit to acquisition or marketing touchpoints. Attribution is an estimate shaped by tracking limits and model assumptions, not objective truth." },
  { id: "an-14", category: "03", group: "product", level: "advanced", mode: "application", frontQuestion: "What should you use to define a small set of critical events and their exact business meaning before building dashboards?", frontScenario: "Different teams call any click “engagement,” making the dashboard look busy but not useful.", answer: "Measurement Framework", backInfo: "A documented mapping from product goals and questions to metrics, events and definitions. It forces teams to measure decisions and outcomes rather than collect data indiscriminately." },
  { id: "an-15", category: "03", group: "product", level: "practice", mode: "distinction", frontQuestion: "Which metric type predicts or influences a later outcome rather than reporting the outcome after it happens?", frontScenario: "The team wants an early signal that retention may improve before waiting 90 days.", answer: "Leading Indicator", backInfo: "A metric expected to move before a desired outcome and provide earlier feedback. It should have evidence linking it to the outcome rather than being chosen only because it moves quickly." },
  { id: "an-16", category: "03", group: "product", level: "practice", mode: "distinction", frontQuestion: "Which metric type confirms an outcome only after the underlying behavior or business result has occurred?", frontScenario: "Quarterly revenue validates whether earlier acquisition and activation efforts ultimately worked.", answer: "Lagging Indicator", backInfo: "A metric that reflects results after the fact. It is useful for outcome validation but often too slow to guide every daily product decision." },
  { id: "ex-01", category: "04", group: "product", level: "foundation", mode: "recall", frontQuestion: "What statement predicts a measurable relationship between a product change and an outcome before you test it?", frontScenario: "A team believes simplifying onboarding will increase first-project creation.", answer: "Hypothesis", backInfo: "A falsifiable prediction connecting a change, target population and expected outcome. A useful hypothesis can be tested and potentially disproved." },
  { id: "ex-02", category: "04", group: "product", level: "foundation", mode: "recall", frontQuestion: "Which experiment compares a control experience with a changed variant using randomized groups?", frontScenario: "Half of eligible users see the current pricing page and half see a redesigned version.", answer: "A/B Test", backInfo: "Randomized controlled experiment comparing variants on predefined outcomes. Random assignment helps isolate causal impact from many confounding factors." },
  { id: "ex-03", category: "04", group: "product", level: "practice", mode: "distinction", frontQuestion: "What is the default statistical claim that an experiment tries to find evidence against?", frontScenario: "Before declaring the redesign better, the analysis assumes there is no true difference between variants.", answer: "Null Hypothesis", backInfo: "Statistical hypothesis typically representing no effect or no difference. Evidence is evaluated against it; failing to reject it is not proof that the variants are identical." },
  { id: "ex-04", category: "04", group: "product", level: "practice", mode: "interpretation", frontQuestion: "Which statistic estimates how compatible observed data is with the null hypothesis under the chosen model?", frontScenario: "An experiment dashboard reports 0.03 and the team wants to know what that number actually means.", answer: "p-value", backInfo: "Probability, assuming the null model is true, of observing data at least as extreme as what was seen. It is not the probability that the hypothesis is true." },
  { id: "ex-05", category: "04", group: "product", level: "practice", mode: "interpretation", frontQuestion: "What interval expresses a range of plausible values for an estimated effect under a specified confidence procedure?", frontScenario: "Conversion improved by 1.2 points, but the team needs to understand uncertainty around that estimate.", answer: "Confidence Interval", backInfo: "Range constructed by a method that would contain the true parameter at the stated rate over repeated samples. It communicates uncertainty better than a point estimate alone." },
  { id: "ex-06", category: "04", group: "product", level: "practice", mode: "recall", frontQuestion: "What is the probability that a test will detect an effect of a specified size when that effect is real?", frontScenario: "A team worries its experiment is too small to detect the conversion improvement it actually cares about.", answer: "Statistical Power", backInfo: "Probability of rejecting the null when a specified real effect exists. Power depends on sample size, variability, significance threshold and effect size." },
  { id: "ex-07", category: "04", group: "product", level: "practice", mode: "application", frontQuestion: "What calculation determines how many observations an experiment needs before it can reliably detect the target effect?", frontScenario: "The team wants to plan test duration before launch instead of stopping as soon as the chart looks positive.", answer: "Sample Size Calculation", backInfo: "Estimates required observations based on baseline, target effect, variability, alpha and power assumptions. It should be planned before reading outcomes whenever possible." },
  { id: "ex-08", category: "04", group: "product", level: "advanced", mode: "recall", frontQuestion: "What is the smallest effect size worth detecting because anything smaller would not change the product decision?", frontScenario: "A 0.05% conversion lift would be statistically detectable at huge scale but commercially irrelevant.", answer: "MDE — Minimum Detectable Effect", backInfo: "Smallest effect the experiment is designed to reliably detect. MDE should reflect decision relevance, not just what is statistically convenient." },
  { id: "ex-09", category: "04", group: "product", level: "practice", mode: "distinction", frontQuestion: "What error happens when you conclude there is an effect even though the null hypothesis is actually true?", frontScenario: "A team ships a variant because of random noise and later cannot reproduce the improvement.", answer: "Type I Error — False Positive", backInfo: "Rejecting a true null hypothesis. The significance level controls the long-run false-positive rate under the model and testing procedure." },
  { id: "ex-10", category: "04", group: "product", level: "practice", mode: "distinction", frontQuestion: "What error happens when a meaningful real effect exists but your test fails to detect it?", frontScenario: "The variant genuinely helps, but the sample was too small and the experiment is called inconclusive.", answer: "Type II Error — False Negative", backInfo: "Failing to reject the null when a relevant effect is real. Higher statistical power reduces the probability of this error for the specified effect size." },
  { id: "ex-11", category: "04", group: "product", level: "practice", mode: "application", frontQuestion: "Which experiment metric protects against harming an important area while optimizing the primary outcome?", frontScenario: "A checkout variant increases purchases but also dramatically increases refund requests.", answer: "Guardrail Metric", backInfo: "A metric monitored to prevent unacceptable harm outside the primary objective, such as errors, latency, cancellations or support load. Guardrails define boundaries, not the main success target." },
  { id: "ex-12", category: "04", group: "product", level: "foundation", mode: "recall", frontQuestion: "What is the single predefined outcome an experiment is mainly designed to evaluate?", frontScenario: "A test changes onboarding and tracks dozens of metrics, but one outcome must determine whether the hypothesis succeeded.", answer: "Primary Metric", backInfo: "Main decision metric specified before analysis. Predefining it reduces cherry-picking among many outcomes after seeing results." },
  { id: "ex-13", category: "04", group: "product", level: "advanced", mode: "interpretation", frontQuestion: "What diagnostic checks whether experiment traffic was split into variants in an unexpectedly different ratio from the intended allocation?", frontScenario: "A 50/50 test receives 63% of users in variant A and 37% in B.", answer: "Sample Ratio Mismatch — SRM", backInfo: "Statistically suspicious deviation between expected and observed allocation. SRM often signals assignment, logging or eligibility bugs and should be investigated before trusting results." },
  { id: "ex-14", category: "04", group: "product", level: "advanced", mode: "interpretation", frontQuestion: "What effect can make a newly introduced feature look unusually strong or weak simply because it is new?", frontScenario: "Users explore a new navigation pattern intensely in week one, then behavior settles back.", answer: "Novelty Effect", backInfo: "Temporary behavior change caused by newness rather than durable product value. Longer observation or follow-up measurement may be needed for lasting effects." },
  { id: "ex-15", category: "04", group: "product", level: "advanced", mode: "distinction", frontQuestion: "What bias occurs when the people observed are systematically different because of how they entered or remained in the sample?", frontScenario: "Only highly engaged customers answer a voluntary survey, making satisfaction look higher than it is across the full user base.", answer: "Selection Bias", backInfo: "Systematic distortion caused by non-random inclusion, exclusion or participation. Better sampling and careful interpretation are needed; bigger samples do not automatically remove it." },
  { id: "ex-16", category: "04", group: "product", level: "advanced", mode: "application", frontQuestion: "What approach lets you inspect experiment data repeatedly using a method designed for sequential decisions rather than ordinary fixed-horizon peeking?", frontScenario: "A team wants to stop tests early when evidence is sufficient without inflating false positives through ad-hoc daily checks.", answer: "Sequential Testing", backInfo: "Statistical methods designed for repeated interim analysis and stopping rules. Do not repeatedly apply a fixed-horizon significance test and stop whenever it crosses a threshold." },
  { id: "uxm-01", category: "05", group: "ux-research", level: "foundation", mode: "recall", frontQuestion: "Which usability metric tells you what share of participants successfully completes a defined task?", frontScenario: "In a usability test, eight of ten participants manage to change their billing address without help.", answer: "Task Success Rate", backInfo: "Percentage of tested attempts that meet predefined success criteria. Define full, partial and failed success consistently if partial success is allowed.", formula: "successful attempts / total attempts × 100." },
  { id: "uxm-02", category: "05", group: "ux-research", level: "foundation", mode: "recall", frontQuestion: "Which metric tells you how long users take to complete a task?", frontScenario: "Two checkout designs both succeed, but one requires much more time.", answer: "Time on Task", backInfo: "Time required to complete a defined task. Interpret alongside success and task complexity; faster is not automatically better when careful review matters." },
  { id: "uxm-03", category: "05", group: "ux-research", level: "practice", mode: "recall", frontQuestion: "Which metric captures how often users make defined mistakes while attempting a task?", frontScenario: "Participants repeatedly enter dates in the wrong format and trigger validation errors.", answer: "Error Rate", backInfo: "Frequency or proportion of defined user errors during a task. Classify errors consistently and distinguish recoverable slips from task failure where useful." },
  { id: "uxm-04", category: "05", group: "ux-research", level: "practice", mode: "distinction", frontQuestion: "Which metric counts how many steps, clicks or actions users need to complete a goal?", frontScenario: "Two flows have similar completion rates, but one requires far more interaction.", answer: "Interaction Cost", backInfo: "Amount of effort required to achieve a goal, often considered through steps, decisions, attention and input rather than a single universal formula. Fewer clicks alone is not always better." },
  { id: "uxm-05", category: "05", group: "ux-research", level: "foundation", mode: "recall", frontQuestion: "Which standardized 10-item questionnaire gives a broad perceived-usability score on a 0–100 scale?", frontScenario: "A team wants a lightweight benchmark of perceived usability before and after a redesign.", answer: "SUS — System Usability Scale", backInfo: "Ten-item standardized usability questionnaire transformed to a 0–100 score. The score is not a percentage and is best interpreted against appropriate comparative data." },
  { id: "uxm-06", category: "05", group: "ux-research", level: "practice", mode: "recall", frontQuestion: "Which one-question post-task rating asks how easy or difficult a just-completed task felt?", frontScenario: "After each usability task, researchers need a quick perceived-difficulty measure.", answer: "SEQ — Single Ease Question", backInfo: "Single-item post-task ease rating, commonly on a 7-point scale. It complements behavioral measures such as task success and time." },
  { id: "uxm-07", category: "05", group: "ux-research", level: "practice", mode: "recall", frontQuestion: "Which compact two-item questionnaire measures perceived usefulness and ease of use?", frontScenario: "A product team needs a very short standardized usability measure inside an ongoing survey.", answer: "UMUX-Lite", backInfo: "Two-item standardized questionnaire focused on usefulness/capability and ease of use. It is useful when survey space is limited." },
  { id: "uxm-08", category: "05", group: "ux-research", level: "foundation", mode: "recall", frontQuestion: "Which metric asks customers how satisfied they are with a product, interaction or support experience?", frontScenario: "After a support conversation, users rate how satisfied they were with the resolution.", answer: "CSAT — Customer Satisfaction Score", backInfo: "Direct satisfaction rating tied to a specified experience. Report the scale and calculation because organizations aggregate CSAT differently." },
  { id: "uxm-09", category: "05", group: "ux-research", level: "foundation", mode: "recall", frontQuestion: "Which metric asks how likely someone is to recommend a product and subtracts detractors from promoters?", frontScenario: "Leadership wants a relationship-level loyalty signal based on the standard recommendation question.", answer: "NPS — Net Promoter Score", backInfo: "Recommendation-based score calculated as percentage of promoters minus percentage of detractors, producing −100 to +100. It should not replace behavioral product metrics or diagnostic research." },
  { id: "uxm-10", category: "05", group: "ux-research", level: "practice", mode: "recall", frontQuestion: "Which metric asks how much effort a customer felt was required to accomplish something?", frontScenario: "A customer successfully updates an account but reports that the process was exhausting.", answer: "CES — Customer Effort Score", backInfo: "Perceived effort associated with a task or service interaction. Exact question wording and scale vary, so document the implementation when comparing results." },
  { id: "uxm-11", category: "05", group: "ux-research", level: "practice", mode: "recall", frontQuestion: "Which metric tells you whether users click the correct first place when starting a navigation task?", frontScenario: "Researchers want an early signal of whether people understand where “Manage team” should live in the navigation.", answer: "First-Click Success", backInfo: "Share of participants whose first click is on a path that can lead to the correct destination. First-click behavior can be highly diagnostic of information scent and navigation clarity." },
  { id: "uxm-12", category: "05", group: "ux-research", level: "practice", mode: "application", frontQuestion: "Which measure combines whether a task succeeds with how efficiently or smoothly it is completed?", frontScenario: "Two designs have the same success rate, but one causes far more hesitation and retries.", answer: "Task Efficiency", backInfo: "Evaluation of successful performance relative to time, actions or effort. Define the calculation for the study; efficiency should be interpreted together with effectiveness and satisfaction." },
  { id: "uxm-13", category: "05", group: "ux-research", level: "advanced", mode: "interpretation", frontQuestion: "Which percentile-based page-experience metric measures how quickly the interface responds after user interactions?", frontScenario: "A web app loads quickly but feels sluggish after clicks and key presses.", answer: "INP — Interaction to Next Paint", backInfo: "Core Web Vital for responsiveness, based on interaction latency over the page lifecycle. In 2026 it is the current responsiveness Core Web Vital; FID is no longer the current Core Web Vital." },
  { id: "uxm-14", category: "05", group: "ux-research", level: "advanced", mode: "distinction", frontQuestion: "Which three metrics form Google's current Core Web Vitals set for loading, responsiveness and visual stability?", frontScenario: "A designer and engineer review real-user web performance and need the current standard trio, not an outdated checklist.", answer: "Core Web Vitals: LCP, INP, CLS", backInfo: "LCP measures loading of the largest content element, INP responsiveness, and CLS visual stability. Current good-experience targets commonly referenced by Google are LCP ≤2.5s, INP ≤200ms and CLS ≤0.1 at the 75th percentile." },
  { id: "ur-01", category: "06", group: "ux-research", level: "foundation", mode: "application", frontQuestion: "Which method observes representative users attempting realistic tasks so you can find usability problems?", frontScenario: "A team needs to see where people fail while booking an appointment in a prototype.", answer: "Usability Testing", backInfo: "Evaluative research in which participants attempt representative tasks while researchers observe behavior and outcomes. It can be moderated or unmoderated and should use clear task goals rather than leading instructions." },
  { id: "ur-02", category: "06", group: "ux-research", level: "foundation", mode: "distinction", frontQuestion: "Which usability-study format includes a researcher who can observe live, ask follow-up questions and manage tasks?", frontScenario: "A complex enterprise workflow requires probing when participants hesitate or use unexpected workarounds.", answer: "Moderated Usability Testing", backInfo: "A facilitator interacts with the participant during the session. It supports probing and complex tasks but introduces facilitator effects and usually requires more time per participant." },
  { id: "ur-03", category: "06", group: "ux-research", level: "foundation", mode: "distinction", frontQuestion: "Which usability-study format lets participants complete tasks independently without a live facilitator?", frontScenario: "The team needs directional evidence from many remote participants across several countries.", answer: "Unmoderated Usability Testing", backInfo: "Participants complete predefined tasks without a live moderator. It scales more easily but offers less ability to probe unexpected behavior in the moment." },
  { id: "ur-04", category: "06", group: "ux-research", level: "foundation", mode: "application", frontQuestion: "Which method uses a guided conversation to understand users' experiences, needs, behaviors and reasoning?", frontScenario: "Before designing a workflow, the team wants to learn how accountants currently reconcile invoices and where the pain occurs.", answer: "User Interview", backInfo: "Qualitative conversation used to understand experiences, motivations, needs and context. Ask about real past behavior and concrete examples rather than relying only on hypothetical preferences." },
  { id: "ur-05", category: "06", group: "ux-research", level: "practice", mode: "application", frontQuestion: "Which method studies people performing real work in their natural environment while the researcher observes and asks questions?", frontScenario: "A designer needs to understand how warehouse staff actually use scanners while moving through a noisy facility.", answer: "Contextual Inquiry", backInfo: "Field research combining observation with in-context questioning. It reveals environmental constraints, tacit workarounds and behaviors that interviews alone may miss." },
  { id: "ur-06", category: "06", group: "ux-research", level: "practice", mode: "application", frontQuestion: "Which method asks participants to record experiences or behaviors repeatedly over days or weeks?", frontScenario: "A sleep app needs to understand changing routines that cannot be captured in one one-hour interview.", answer: "Diary Study", backInfo: "Longitudinal self-report method where participants document experiences over time. Useful for intermittent, emotional or context-dependent behavior, but participant effort and reporting quality must be managed." },
  { id: "ur-07", category: "06", group: "ux-research", level: "practice", mode: "distinction", frontQuestion: "Which broad research approach observes behavior in the real environment rather than in a lab or remote test setup?", frontScenario: "The product is used differently on construction sites than people describe in office interviews.", answer: "Field Study", backInfo: "Research conducted in the participant's real context to understand behavior, environment and constraints. It can include observation, interviews and contextual inquiry techniques." },
  { id: "ur-08", category: "06", group: "ux-research", level: "foundation", mode: "application", frontQuestion: "Which method collects structured responses from many people to quantify attitudes, characteristics or self-reported behavior?", frontScenario: "The team wants to estimate how common several reported problems are across a large customer base.", answer: "Survey", backInfo: "Structured questionnaire suited to breadth and quantification of self-report. Good survey design requires neutral wording, appropriate scales, sampling awareness and careful interpretation." },
  { id: "ur-09", category: "06", group: "ux-research", level: "foundation", mode: "application", frontQuestion: "Which IA method asks participants to group content into categories that make sense to them?", frontScenario: "A documentation site has hundreds of topics and the team wants evidence for how users mentally group them.", answer: "Card Sorting", backInfo: "Participants organize items into categories to reveal mental models and labeling patterns. It informs IA but does not by itself validate final navigation performance." },
  { id: "ur-10", category: "06", group: "ux-research", level: "practice", mode: "distinction", frontQuestion: "Which card-sort format lets participants create and name their own categories?", frontScenario: "The team has little confidence in its current taxonomy and wants to discover users' natural groupings.", answer: "Open Card Sort", backInfo: "Participants group items and create category labels. Best for generative understanding of mental models rather than testing a fixed taxonomy." },
  { id: "ur-11", category: "06", group: "ux-research", level: "practice", mode: "distinction", frontQuestion: "Which card-sort format asks participants to sort items into categories that already exist?", frontScenario: "The team has proposed navigation labels and wants to see where users expect each item to belong.", answer: "Closed Card Sort", backInfo: "Participants place items into predefined categories. Useful for evaluating an existing categorization scheme, though it constrains possible structures." },
  { id: "ur-12", category: "06", group: "ux-research", level: "foundation", mode: "application", frontQuestion: "Which method tests whether people can find destinations in a text-only hierarchy without visual design influencing them?", frontScenario: "A team wants to validate a new site structure before building screens.", answer: "Tree Testing", backInfo: "Participants navigate a simplified hierarchy to find specified items. It tests findability and labeling of the information architecture independently of page visual design." },
  { id: "ur-13", category: "06", group: "ux-research", level: "practice", mode: "application", frontQuestion: "Which study tests whether a product idea or value proposition makes sense before detailed interaction design exists?", frontScenario: "A company has three service concepts and wants to learn which problems and propositions resonate before investing in UI.", answer: "Concept Testing", backInfo: "Evaluates understanding, relevance, appeal and concerns around an early concept. It tests the concept, not proof of future market success." },
  { id: "ur-14", category: "06", group: "ux-research", level: "foundation", mode: "application", frontQuestion: "Which study uses an interactive representation of a future product to test workflows before full implementation?", frontScenario: "Engineering has not built the feature, but the team needs to observe whether users understand the proposed flow.", answer: "Prototype Testing", backInfo: "Evaluation using a prototype of suitable fidelity to answer specific questions. Prototype behavior and limitations should match the research goal closely enough to avoid misleading conclusions." },
  { id: "ur-15", category: "06", group: "ux-research", level: "practice", mode: "application", frontQuestion: "Which expert-review method checks an interface against established usability principles without recruiting participants?", frontScenario: "The team needs a fast structured review before scheduling user testing.", answer: "Heuristic Evaluation", backInfo: "Experts inspect an interface against usability heuristics to identify likely issues. It is efficient but does not replace evidence from actual users." },
  { id: "ur-16", category: "06", group: "ux-research", level: "practice", mode: "application", frontQuestion: "Which expert method walks through a task step by step to judge whether a new or infrequent user will know what to do next?", frontScenario: "A complex setup flow is designed for first-time administrators, and the team wants to inspect learnability.", answer: "Cognitive Walkthrough", backInfo: "Step-by-step expert evaluation focused on whether users can form the right goal, notice controls, associate actions with goals and understand feedback." },
  { id: "ur-17", category: "06", group: "ux-research", level: "practice", mode: "recall", frontQuestion: "What document defines who qualifies for a study so recruitment matches the research question?", frontScenario: "A study about first-time mortgage applicants accidentally recruits finance professionals who know the process too well.", answer: "Screener", backInfo: "Recruitment questionnaire used to include or exclude participants based on relevant characteristics and behavior. Criteria should reflect the target population without revealing desired answers." },
  { id: "ur-18", category: "06", group: "ux-research", level: "advanced", mode: "distinction", frontQuestion: "What principle describes the point where additional qualitative sessions produce little genuinely new insight for the research question?", frontScenario: "After many interviews, the same themes repeat and new sessions mostly confirm existing patterns.", answer: "Saturation", backInfo: "A qualitative-research concept indicating diminishing emergence of new relevant themes. It is context-dependent and should not be used as a mechanical universal participant-count rule." },
  { id: "pd-01", category: "07", group: "product", level: "foundation", mode: "distinction", frontQuestion: "What space contains customer needs, pains and desired outcomes before you decide what to build?", frontScenario: "A team keeps debating feature ideas before agreeing on the actual customer problem.", answer: "Problem Space", backInfo: "The domain of user/customer needs, problems, constraints and outcomes to understand before committing to solutions. Staying in the problem space long enough reduces premature solution fixation." },
  { id: "pd-02", category: "07", group: "product", level: "foundation", mode: "distinction", frontQuestion: "What space contains the possible products, features, workflows or interventions that could address a validated problem?", frontScenario: "The team understands that freelancers struggle with invoice follow-up and now explores several ways to help.", answer: "Solution Space", backInfo: "The set of possible ways to address an opportunity or problem. Multiple solutions should usually be compared rather than treating the first idea as inevitable." },
  { id: "pd-03", category: "07", group: "product", level: "foundation", mode: "recall", frontQuestion: "What should discovery start with when the team needs a clear measurable change in customer or business behavior rather than a feature request?", frontScenario: "Leadership says “build AI search,” but the team first needs to define what improvement that feature is supposed to create.", answer: "Desired Outcome", backInfo: "A measurable result the team is trying to influence. Outcomes help keep discovery focused on change in behavior or value instead of output volume." },
  { id: "pd-04", category: "07", group: "product", level: "foundation", mode: "recall", frontQuestion: "What term describes an unmet customer need, pain point or desire that could help drive the desired outcome if addressed?", frontScenario: "Interview after interview reveals that buyers cannot compare plans confidently before checkout.", answer: "Opportunity", backInfo: "A customer need, pain point or desire worth exploring in relation to an outcome. In continuous discovery, opportunities are not solution ideas." },
  { id: "pd-05", category: "07", group: "product", level: "foundation", mode: "recall", frontQuestion: "What is a belief that must be true for a proposed solution or plan to succeed but has not yet been proven?", frontScenario: "The team assumes users will trust an automated recommendation enough to act on it.", answer: "Assumption", backInfo: "An unverified belief underlying a product decision. Good discovery makes assumptions explicit so the riskiest ones can be tested cheaply." },
  { id: "pd-06", category: "07", group: "product", level: "practice", mode: "distinction", frontQuestion: "Which product risk asks whether customers actually want or value the proposed solution?", frontScenario: "The feature is technically possible, but nobody knows whether users care enough to change behavior or pay.", answer: "Value Risk", backInfo: "Risk that the solution does not create sufficient customer/user value. Test desirability, relevance, behavior and willingness before assuming demand." },
  { id: "pd-07", category: "07", group: "product", level: "practice", mode: "distinction", frontQuestion: "Which product risk asks whether users can understand and successfully use the proposed experience?", frontScenario: "Customers want the feature, but early prototypes show they cannot configure it correctly.", answer: "Usability Risk", backInfo: "Risk that intended users cannot effectively or efficiently use the solution. Prototypes and usability testing are common ways to reduce it." },
  { id: "pd-08", category: "07", group: "product", level: "practice", mode: "distinction", frontQuestion: "Which product risk asks whether the team can build and operate the solution with available technology, data and constraints?", frontScenario: "A concept depends on near-real-time predictions, but the current data pipeline updates once per day.", answer: "Feasibility Risk", backInfo: "Risk that the solution cannot be delivered reliably with available technical capabilities, time or infrastructure. Engineering and data input is essential during discovery." },
  { id: "pd-09", category: "07", group: "product", level: "practice", mode: "distinction", frontQuestion: "Which product risk asks whether the solution works for the business, legal model, operations and other organizational constraints?", frontScenario: "Users love an idea, but servicing it manually would make every transaction unprofitable.", answer: "Viability Risk", backInfo: "Risk that the solution cannot sustainably work for the business or organization. It includes economics, legal/compliance, operations, strategy and stakeholder constraints." },
  { id: "pd-10", category: "07", group: "product", level: "practice", mode: "application", frontQuestion: "What should a team test first when one unproven belief could invalidate the whole solution?", frontScenario: "A marketplace prototype looks polished, but success depends on sellers agreeing to respond within five minutes.", answer: "Riskiest Assumption", backInfo: "The assumption whose failure would most seriously undermine the idea, considering both uncertainty and importance. Test it before polishing lower-risk details." },
  { id: "pd-11", category: "07", group: "product", level: "practice", mode: "application", frontQuestion: "Which technique maps assumptions by importance and evidence so the team can decide what to test first?", frontScenario: "A product trio has twenty assumptions and needs a rational order for validation.", answer: "Assumption Mapping", backInfo: "Visual or structured prioritization of assumptions, commonly by importance/risk and level of evidence. It helps focus experiments on what could most change the decision." },
  { id: "pd-12", category: "07", group: "product", level: "practice", mode: "application", frontQuestion: "Which low-cost test measures interest in a feature before the full feature exists, for example with a button or landing page?", frontScenario: "The team is unsure whether customers want an export feature and wants evidence before spending six weeks building it.", answer: "Fake Door Test", backInfo: "An experiment exposing a realistic entry point to an unbuilt capability and measuring expressed behavior such as clicks or sign-ups. Be transparent enough to avoid deceptive or harmful experiences." },
  { id: "pd-13", category: "07", group: "product", level: "practice", mode: "application", frontQuestion: "Which validation approach manually delivers the service to a small number of customers to learn what creates value before automating it?", frontScenario: "A startup personally creates weekly reports for five customers before investing in a reporting engine.", answer: "Concierge Test", backInfo: "Humans intentionally provide the value manually while learning about needs, workflow and willingness to use/pay. The manual nature is typically visible to participants." },
  { id: "pd-14", category: "07", group: "product", level: "practice", mode: "distinction", frontQuestion: "Which prototype approach makes a system appear automated to the user while humans secretly perform some of the operation behind the scenes?", frontScenario: "A team tests an “AI” categorization flow before the model exists by having an operator classify requests manually.", answer: "Wizard of Oz Prototype", backInfo: "A prototype where users experience apparently automated behavior that is actually produced manually behind the scenes. It is useful for testing interaction/value before building expensive automation." },
  { id: "pd-15", category: "07", group: "product", level: "foundation", mode: "recall", frontQuestion: "What cross-functional group commonly combines product, design and engineering perspectives during continuous discovery?", frontScenario: "Decisions are stronger when customer value, experience and technical constraints are explored together instead of handed off sequentially.", answer: "Product Trio", backInfo: "A collaborative product manager, designer and engineer grouping popularized in continuous discovery practice. It is a collaboration model, not a mandatory org-chart rule." },
  { id: "pd-16", category: "07", group: "product", level: "practice", mode: "recall", frontQuestion: "What practice means engaging with customers and testing assumptions frequently throughout product work rather than in occasional research phases?", frontScenario: "The team speaks with customers weekly and continuously tests opportunities and solutions alongside delivery.", answer: "Continuous Discovery", backInfo: "Ongoing discovery aimed at reducing product risk through frequent customer contact, opportunity framing and assumption testing. It complements delivery rather than being a one-time “discovery phase.”" },
  { id: "sp-01", category: "08", group: "product", level: "foundation", mode: "recall", frontQuestion: "What describes the long-term future state you want the product or organization to help create?", frontScenario: "A team needs a durable direction that can outlast individual features and quarterly plans.", answer: "Product Vision", backInfo: "An aspirational description of the future the product is working toward. It provides direction, not a detailed execution plan." },
  { id: "sp-02", category: "08", group: "product", level: "foundation", mode: "distinction", frontQuestion: "What describes why the organization or product exists and whom it serves today?", frontScenario: "The team needs a concise statement of purpose rather than a future-state aspiration.", answer: "Mission", backInfo: "Statement of present purpose: why the organization/product exists, whom it serves and often what value it creates. It is distinct from a future-oriented vision." },
  { id: "sp-03", category: "08", group: "product", level: "foundation", mode: "recall", frontQuestion: "What set of choices explains where the product will compete and how it intends to win or create differentiated value?", frontScenario: "The roadmap contains dozens of requests, but there is no logic for why some markets and problems matter more than others.", answer: "Product Strategy", backInfo: "Coherent set of choices connecting vision to target customers, problems, differentiation, capabilities and trade-offs. Strategy requires saying no to some attractive options." },
  { id: "sp-04", category: "08", group: "product", level: "practice", mode: "recall", frontQuestion: "What is a deliberate high-level commitment to a direction whose success is uncertain but strategically important?", frontScenario: "The company chooses to make collaboration its main growth lever for the next year rather than adding unrelated features.", answer: "Strategic Bet", backInfo: "A meaningful resource commitment based on a strategic belief about how to create advantage or reach an outcome. Bets should have explicit assumptions and signals for learning." },
  { id: "sp-05", category: "08", group: "product", level: "foundation", mode: "recall", frontQuestion: "What artifact communicates intended product direction and sequencing over time without being a guaranteed feature contract?", frontScenario: "Stakeholders need to understand what themes the team expects to pursue and why.", answer: "Product Roadmap", backInfo: "Communication artifact showing product direction, priorities and expected progression. A roadmap should adapt as evidence changes; it is not automatically a fixed delivery schedule." },
  { id: "sp-06", category: "08", group: "product", level: "practice", mode: "distinction", frontQuestion: "What roadmap organizes work around problems or measurable outcomes instead of promising named features by date?", frontScenario: "The team wants to align on “reduce failed first-time setup” rather than commit six months early to one solution.", answer: "Outcome-based Roadmap", backInfo: "Roadmap structured around outcomes, customer problems or strategic themes. It preserves room to discover the best solution while maintaining direction." },
  { id: "sp-07", category: "08", group: "product", level: "foundation", mode: "recall", frontQuestion: "What goal-setting system pairs a qualitative objective with measurable key results?", frontScenario: "A team wants ambitious direction plus evidence that tells whether it moved toward that direction.", answer: "OKR — Objectives and Key Results", backInfo: "Framework combining a qualitative objective with a small set of measurable results. Key results should describe outcomes, not simply list tasks completed." },
  { id: "sp-08", category: "08", group: "product", level: "foundation", mode: "distinction", frontQuestion: "In an OKR, what is the qualitative description of the change or direction the team wants to achieve?", frontScenario: "“Make first-time setup effortless for new teams” expresses intent but not the measurement.", answer: "Objective", backInfo: "Qualitative, directional goal in an OKR. It answers what meaningful change the team is pursuing." },
  { id: "sp-09", category: "08", group: "product", level: "foundation", mode: "distinction", frontQuestion: "In an OKR, what is the measurable evidence used to determine whether the objective was achieved?", frontScenario: "The team needs numbers such as activation increase and setup-time reduction rather than a list of shipped features.", answer: "Key Result", backInfo: "Quantified outcome used to assess progress toward an objective. Shipping a feature is usually an initiative, not a strong key result by itself." },
  { id: "sp-10", category: "08", group: "product", level: "foundation", mode: "application", frontQuestion: "Which prioritization framework scores initiatives using Reach, Impact, Confidence and Effort?", frontScenario: "A team must compare ideas that affect different numbers of users and require different engineering effort.", answer: "RICE", backInfo: "Prioritization model using Reach × Impact × Confidence / Effort. Useful for structured comparison, but scores depend on assumptions and should not replace strategic judgment." },
  { id: "sp-11", category: "08", group: "product", level: "practice", mode: "distinction", frontQuestion: "Which lightweight prioritization framework scores ideas using Impact, Confidence and Ease?", frontScenario: "An early-stage team wants a faster scoring model than RICE because reliable reach estimates are unavailable.", answer: "ICE", backInfo: "Prioritization model based on Impact, Confidence and Ease. It is quick but highly subjective unless teams define consistent scoring scales." },
  { id: "sp-12", category: "08", group: "product", level: "practice", mode: "application", frontQuestion: "Which prioritization method divides Cost of Delay by job size to favor high-value work that can be delivered sooner?", frontScenario: "A portfolio team must sequence initiatives where urgency and effort differ substantially.", answer: "WSJF — Weighted Shortest Job First", backInfo: "Prioritization approach popular in scaled agile contexts. Useful for sequencing economic value, but the input estimates still require judgment.", formula: "Cost of Delay / Job Size." },
  { id: "sp-13", category: "08", group: "product", level: "foundation", mode: "recall", frontQuestion: "Which prioritization method classifies scope as Must, Should, Could and Won't have for a given period or release?", frontScenario: "A client project has more requested features than can fit the release and needs explicit scope categories.", answer: "MoSCoW", backInfo: "Scope-prioritization method: Must have, Should have, Could have, Won't have this time. Teams must limit “Must” items or the classification becomes meaningless." },
  { id: "sp-14", category: "08", group: "product", level: "foundation", mode: "application", frontQuestion: "Which simple prioritization tool plots expected impact against required effort?", frontScenario: "A team wants to identify quick wins and avoid spending months on low-impact ideas.", answer: "Impact–Effort Matrix", backInfo: "2×2 or continuous comparison of expected impact and effort. Useful for discussion and triage, but it ignores factors such as confidence, timing and strategic fit unless added explicitly." },
  { id: "sp-15", category: "08", group: "product", level: "practice", mode: "application", frontQuestion: "Which model classifies product attributes by how their presence or absence affects customer satisfaction?", frontScenario: "Some capabilities are basic expectations, while others can delight customers even though they were not expected.", answer: "Kano Model", backInfo: "Classifies attributes such as basic/must-be, performance and delighters based on satisfaction response. Categories can change over time as expectations evolve." },
  { id: "sp-16", category: "08", group: "product", level: "advanced", mode: "recall", frontQuestion: "Which concept expresses the economic loss or missed value caused by delaying a piece of work?", frontScenario: "Postponing a regulatory change and postponing a cosmetic improvement have very different consequences even if effort is equal.", answer: "Cost of Delay", backInfo: "Estimate of value lost as work waits, including revenue, risk, customer impact or time-critical opportunity. It helps make urgency explicit." },
  { id: "sp-17", category: "08", group: "product", level: "practice", mode: "application", frontQuestion: "Which method prioritizes opportunities by combining their importance to customers with current satisfaction?", frontScenario: "Users care strongly about a workflow but are very dissatisfied with current solutions, suggesting room for improvement.", answer: "Opportunity Scoring", backInfo: "Prioritization approach that compares the importance of outcomes/needs with satisfaction with existing solutions. Exact formulas vary; the purpose is to identify important underserved outcomes." },
  { id: "sp-18", category: "08", group: "product", level: "foundation", mode: "recall", frontQuestion: "In Scrum, what long-term objective provides a target for the product and gives direction to the Product Backlog?", frontScenario: "A Scrum team needs a coherent future state to work toward across multiple Sprints.", answer: "Product Goal", backInfo: "The long-term objective for the Scrum Team defined in the Product Backlog. It provides focus beyond an individual Sprint Goal." },
  { id: "fw-01", category: "09", group: "product", level: "foundation", mode: "recall", frontQuestion: "Which perspective frames customer demand around the progress a person is trying to make rather than around demographic traits or requested features?", frontScenario: "Two very different customers “hire” the same tool because both need to coordinate a complex decision quickly.", answer: "Jobs to Be Done — JTBD", backInfo: "A way to understand products through the progress customers seek in a situation. Focus on the job/context and desired progress rather than treating personas or feature requests as the explanation by themselves." },
  { id: "fw-02", category: "09", group: "product", level: "practice", mode: "application", frontQuestion: "Which sentence format expresses a user's situation, motivation and desired outcome as “When…, I want to…, so I can…”?", frontScenario: "The team wants to describe context and motivation without turning the requirement into a feature-specific user story.", answer: "Job Story", backInfo: "JTBD-style framing: When [situation], I want to [motivation], so I can [expected outcome]. It emphasizes context and progress rather than role labels alone." },
  { id: "fw-03", category: "09", group: "product", level: "advanced", mode: "interpretation", frontQuestion: "Which JTBD idea examines the push away from the current situation, pull of a new solution, habits of the present and anxieties about change?", frontScenario: "Customers say they want a better tool but still do not switch; the team needs to understand forces both for and against change.", answer: "Forces of Progress", backInfo: "JTBD lens describing forces that drive or resist switching: push, pull, habits/inertia and anxieties. It is useful for understanding adoption and switching behavior." },
  { id: "fw-04", category: "09", group: "product", level: "foundation", mode: "recall", frontQuestion: "Which design framework alternates divergent and convergent thinking across Discover, Define, Develop and Deliver?", frontScenario: "A team needs a simple shared model for exploring the problem broadly, narrowing it, exploring solutions and narrowing again.", answer: "Double Diamond", backInfo: "Design Council model with two divergence/convergence cycles: Discover, Define, Develop, Deliver. It is a thinking model, not a requirement that real projects proceed linearly." },
  { id: "fw-05", category: "09", group: "product", level: "foundation", mode: "recall", frontQuestion: "Which human-centered approach commonly uses empathize, define, ideate, prototype and test as iterative activities?", frontScenario: "A workshop needs a familiar structure for moving from user understanding to tested concepts.", answer: "Design Thinking", backInfo: "Broad human-centered problem-solving approach commonly represented through empathize, define, ideate, prototype and test. In practice the activities are iterative, not a rigid five-step waterfall." },
  { id: "fw-06", category: "09", group: "product", level: "practice", mode: "recall", frontQuestion: "Which approach combines Lean Startup ideas with collaborative UX work, rapid assumptions and learning through small experiments?", frontScenario: "A product team wants less documentation-for-handoff and more shared hypotheses, prototypes and learning.", answer: "Lean UX", backInfo: "Collaborative approach emphasizing assumptions, hypotheses, rapid experimentation and outcomes over heavy deliverables. It works best when design, product and engineering learn together." },
  { id: "fw-07", category: "09", group: "product", level: "foundation", mode: "recall", frontQuestion: "Which growth framework organizes the customer lifecycle into Acquisition, Activation, Retention, Referral and Revenue?", frontScenario: "A startup wants a simple lens to locate whether growth problems occur before first value, after first value or in monetization.", answer: "AARRR — Pirate Metrics", backInfo: "Lifecycle framework: Acquisition, Activation, Retention, Referral, Revenue. It is a diagnostic structure, not a prescription that every business optimizes each stage equally." },
  { id: "fw-08", category: "09", group: "product", level: "practice", mode: "recall", frontQuestion: "Which UX measurement framework groups signals into Happiness, Engagement, Adoption, Retention and Task Success?", frontScenario: "A team wants a broad way to select user-experience measures without relying on one satisfaction score.", answer: "HEART Framework", backInfo: "Google-originated UX metrics framework: Happiness, Engagement, Adoption, Retention, Task Success. Teams typically map goals to signals and metrics within relevant categories." },
  { id: "fw-09", category: "09", group: "product", level: "practice", mode: "application", frontQuestion: "Which visual discovery framework connects a desired outcome to customer opportunities, possible solutions and assumption tests?", frontScenario: "Interview findings and solution ideas are scattered across documents and the team needs one structure to keep discovery aligned.", answer: "Opportunity Solution Tree — OST", backInfo: "Continuous-discovery visual that links an outcome to an opportunity space, solution ideas and tests/assumptions. It helps teams compare paths rather than jumping from outcome directly to one feature." },
  { id: "fw-10", category: "09", group: "product", level: "foundation", mode: "application", frontQuestion: "Which canvas connects customer jobs, pains and gains with products/services, pain relievers and gain creators?", frontScenario: "A team needs to check whether a proposed value proposition actually responds to what a target customer is trying to accomplish.", answer: "Value Proposition Canvas", backInfo: "Strategyzer framework pairing Customer Profile with Value Map. Useful for articulating fit hypotheses; it still requires customer evidence rather than workshop consensus alone." },
  { id: "fw-11", category: "09", group: "product", level: "foundation", mode: "application", frontQuestion: "Which one-page framework maps key partners, activities, resources, value propositions, customer relationships, channels, segments, costs and revenues?", frontScenario: "A founder wants to make the assumptions behind a new business model visible on one page.", answer: "Business Model Canvas", backInfo: "Nine-block model for describing how an organization creates, delivers and captures value. It is a hypothesis map, not proof that the business model works." },
  { id: "fw-12", category: "09", group: "product", level: "practice", mode: "application", frontQuestion: "Which map shows the customer journey together with frontstage interactions, backstage processes, people and supporting systems?", frontScenario: "A service problem looks like a UI issue, but the root cause is actually an internal approval process and delayed data sync.", answer: "Service Blueprint", backInfo: "Service-design map linking customer actions and touchpoints to visible employee/system interactions, backstage processes and support infrastructure. Useful for cross-channel services." },
  { id: "fw-13", category: "09", group: "product", level: "foundation", mode: "application", frontQuestion: "Which artifact maps a customer's stages, actions, thoughts, emotions and touchpoints across an end-to-end goal?", frontScenario: "A team wants to understand the experience of choosing, buying, onboarding and getting support rather than only one screen.", answer: "Customer Journey Map", backInfo: "Visualization of a specific customer's experience over time toward a goal. Good journey maps are grounded in evidence and scoped to a defined actor and scenario." },
  { id: "fw-14", category: "09", group: "product", level: "practice", mode: "distinction", frontQuestion: "Which map is broader than a single product and represents a person's experience around a domain or goal across channels and services?", frontScenario: "The team studies “moving home” including agents, banks, utilities and government services, not just its own app.", answer: "Experience Map", backInfo: "End-to-end representation of a broader human experience that may cross products and organizations. It is typically less product-specific than a customer journey map." },
  { id: "fw-15", category: "09", group: "product", level: "practice", mode: "application", frontQuestion: "Which planning technique arranges user activities and tasks horizontally by journey and slices releases vertically by value?", frontScenario: "A team needs to see the whole workflow while choosing the smallest coherent first release.", answer: "User Story Mapping", backInfo: "Jeff Patton's technique for organizing work around the user journey/activity flow and slicing releases. It helps preserve end-to-end value instead of prioritizing isolated backlog items." },
  { id: "fw-16", category: "09", group: "product", level: "advanced", mode: "application", frontQuestion: "Which JTBD-style map breaks a core job into universal process steps such as defining, locating, preparing, confirming, executing and monitoring?", frontScenario: "A team wants to find innovation opportunities across the entire job rather than around its existing feature set.", answer: "Job Map", backInfo: "Structured view of the steps customers go through to accomplish a job, independent of a specific solution. Useful for identifying unmet needs across the full job process." },
  { id: "ia-01", category: "10", group: "design", level: "foundation", mode: "recall", frontQuestion: "What discipline organizes and structures information so people can understand where they are and find what they need?", frontScenario: "A platform has hundreds of pages, tools and settings but users cannot predict where anything lives.", answer: "Information Architecture — IA", backInfo: "Practice of structuring, organizing, labeling and connecting information to support understanding and findability. IA includes more than drawing a sitemap." },
  { id: "ia-02", category: "10", group: "design", level: "foundation", mode: "recall", frontQuestion: "What controlled classification system defines categories and relationships used to organize content or objects?", frontScenario: "A marketplace calls the same product “audio,” “headphones” and “personal sound” in different places.", answer: "Taxonomy", backInfo: "System for classifying and naming content/items into consistent categories. A useful taxonomy reflects user mental models and operational needs." },
  { id: "ia-03", category: "10", group: "design", level: "foundation", mode: "recall", frontQuestion: "What concept describes levels of importance or parent–child structure within content and navigation?", frontScenario: "Account settings contain top-level sections, sub-sections and individual controls.", answer: "Hierarchy", backInfo: "Ordered structure expressing levels, grouping or priority. Clear hierarchy reduces cognitive effort and helps people predict where information belongs." },
  { id: "ia-04", category: "10", group: "design", level: "foundation", mode: "recall", frontQuestion: "What diagram represents the planned structure and relationships of pages or screens in a site or product?", frontScenario: "Before redesigning a documentation portal, the team needs a shared structural overview.", answer: "Sitemap", backInfo: "Representation of pages/screens and their hierarchical relationships. It documents structure but does not prove that users can find items within it." },
  { id: "ia-05", category: "10", group: "design", level: "foundation", mode: "recall", frontQuestion: "What system of menus, links and controls helps users move through a product's information structure?", frontScenario: "Users understand individual pages but repeatedly get lost moving between projects, settings and billing.", answer: "Navigation", backInfo: "Mechanisms that let users move among locations or content. Good navigation provides clear choices, orientation and predictable routes." },
  { id: "ia-06", category: "10", group: "design", level: "foundation", mode: "application", frontQuestion: "What practice chooses names for categories, menus and controls so users can predict what they contain or do?", frontScenario: "Internal teams say “Workspace Orchestration,” while customers look for “Team settings.”", answer: "Labeling", backInfo: "Naming information and actions using language users can understand and distinguish. Labels should be specific, consistent and tested in context." },
  { id: "ia-07", category: "10", group: "design", level: "foundation", mode: "recall", frontQuestion: "What is the user's internal expectation of how a system or domain works?", frontScenario: "Customers expect deleted files to behave like a familiar trash/recycle bin even though the backend implementation is different.", answer: "Mental Model", backInfo: "Internal representation people use to predict how something works. Interfaces are easier to learn when conceptual models align with relevant user expectations." },
  { id: "ia-08", category: "10", group: "design", level: "practice", mode: "recall", frontQuestion: "What cue helps users predict what they will find after following a label, link or navigation path?", frontScenario: "A menu item called “Resources” gives little clue whether it contains templates, billing help or documentation.", answer: "Information Scent", backInfo: "Signals that help users judge whether a path is likely to lead to their goal. Specific labels and contextual cues strengthen information scent." },
  { id: "ia-09", category: "10", group: "design", level: "foundation", mode: "recall", frontQuestion: "What quality describes how easily users can locate information or functionality when they need it?", frontScenario: "The feature exists and works perfectly, but customers keep contacting support because they cannot locate it.", answer: "Findability", backInfo: "Degree to which information or functionality can be discovered and located. It depends on IA, navigation, search, labels and information scent." },
  { id: "ia-10", category: "10", group: "design", level: "practice", mode: "recall", frontQuestion: "What structured definition describes content types, their fields and relationships independently of a specific screen layout?", frontScenario: "A CMS must support articles, authors, products and reusable FAQs across web and mobile.", answer: "Content Model", backInfo: "Definition of content types, attributes and relationships. It separates semantic content structure from one particular presentation." },
  { id: "ia-11", category: "10", group: "design", level: "foundation", mode: "recall", frontQuestion: "What do you call short interface text such as button labels, field hints, empty-state copy and error messages?", frontScenario: "A designer must decide whether a button says “Save,” “Apply changes” or “Update profile.”", answer: "Microcopy", backInfo: "Small pieces of product-interface content that guide actions, explain states and reduce uncertainty. Good microcopy is specific, concise and contextual." },
  { id: "ia-12", category: "10", group: "design", level: "foundation", mode: "distinction", frontQuestion: "What defines the consistent personality and style of a product's communication across contexts?", frontScenario: "A brand wants to sound clear, calm and slightly playful across onboarding, help and marketing.", answer: "Voice", backInfo: "Stable character of how a product or brand communicates. Voice is relatively consistent; tone adapts to the situation." },
  { id: "ia-13", category: "10", group: "design", level: "foundation", mode: "distinction", frontQuestion: "What changes the emotional delivery of the same brand voice depending on the user's situation?", frontScenario: "The product can be playful after a success but should be calm and direct when a payment fails.", answer: "Tone", backInfo: "Context-sensitive expression of the underlying voice. Tone should respond to user emotion, risk and task without becoming a different brand personality." },
  { id: "ia-14", category: "10", group: "design", level: "foundation", mode: "application", frontQuestion: "What writing approach prioritizes familiar words, direct structure and easy comprehension instead of jargon or bureaucratic phrasing?", frontScenario: "A consent flow is legally important but currently reads like an internal policy document.", answer: "Plain Language", backInfo: "Writing so the intended audience can find, understand and use information easily. Plain language is not childish language; it reduces unnecessary complexity while preserving accuracy." },
  { id: "ix-01", category: "11", group: "design", level: "foundation", mode: "recall", frontQuestion: "What property of an object or interface suggests what actions are possible with it?", frontScenario: "A raised button-like control appears pressable even before the user reads its label.", answer: "Affordance", backInfo: "Possibilities for action offered by an object or environment relative to a user. In UI discussion, distinguish the underlying affordance from the visual cue that communicates it." },
  { id: "ix-02", category: "11", group: "design", level: "foundation", mode: "distinction", frontQuestion: "What visible or perceivable cue communicates where an action can be taken?", frontScenario: "Underlined blue text signals that it can be clicked even though the underlying action is simply navigation.", answer: "Signifier", backInfo: "Perceivable signal that indicates an affordance or where/how to act. Labels, icons, shape, placement and styling can all function as signifiers." },
  { id: "ix-03", category: "11", group: "design", level: "foundation", mode: "recall", frontQuestion: "What response from the system tells users that their action was received and what happened?", frontScenario: "After pressing “Save,” the screen changes state and confirms success rather than leaving the user uncertain.", answer: "Feedback", backInfo: "System response to an action that communicates status or result. Feedback should be timely, perceivable and proportional to the action." },
  { id: "ix-04", category: "11", group: "design", level: "practice", mode: "recall", frontQuestion: "What relationship makes control behavior correspond naturally to the effect it produces?", frontScenario: "Dragging a map left causes the viewed world to move in a spatially understandable direction.", answer: "Mapping", backInfo: "Relationship between controls/actions and their effects. Natural mapping reduces learning effort by matching spatial or conceptual expectations." },
  { id: "ix-05", category: "11", group: "design", level: "foundation", mode: "recall", frontQuestion: "What design mechanism limits possible actions to prevent invalid or unsafe states?", frontScenario: "“Submit” remains unavailable until all required information is valid.", answer: "Constraint", backInfo: "Restriction that narrows available actions or states. Constraints can prevent errors, but disabled options should not hide why progress is blocked." },
  { id: "ix-06", category: "11", group: "design", level: "foundation", mode: "application", frontQuestion: "Which principle says users should be able to understand what the system is currently doing?", frontScenario: "A file upload takes 20 seconds with no progress indicator, so users repeatedly click upload.", answer: "Visibility of System Status", backInfo: "Usability principle: keep users informed about current state through appropriate, timely feedback. Progress, saving, syncing and errors should not be invisible when they matter." },
  { id: "ix-07", category: "11", group: "design", level: "foundation", mode: "recall", frontQuestion: "Which principle reduces learning effort by making similar elements and behaviors work in similar ways?", frontScenario: "“Save” is in the same place across settings pages and destructive actions follow the same confirmation pattern.", answer: "Consistency", backInfo: "Reuse of patterns, language and behavior so knowledge transfers across the product. Consistency should support understanding, not preserve a bad pattern forever." },
  { id: "ix-08", category: "11", group: "design", level: "foundation", mode: "distinction", frontQuestion: "Which principle favors showing recognizable options and cues instead of forcing users to remember information from another screen?", frontScenario: "A checkout shows saved delivery addresses rather than asking users to recall and retype them.", answer: "Recognition over Recall", backInfo: "Reduce memory load by making actions, objects and relevant information visible or retrievable. Recall is sometimes unavoidable, but the interface should not require unnecessary memorization." },
  { id: "ix-09", category: "11", group: "design", level: "foundation", mode: "application", frontQuestion: "Which law predicts that targets are faster to acquire when they are larger and/or closer?", frontScenario: "A mobile primary action is tiny and placed far from the thumb's natural reach.", answer: "Fitts's Law", backInfo: "Movement time depends on target distance and size. In interface design it supports adequately sized, reachable targets, while context and motor accessibility still matter." },
  { id: "ix-10", category: "11", group: "design", level: "foundation", mode: "application", frontQuestion: "Which law predicts that decision time tends to increase as the number and complexity of choices increases?", frontScenario: "A menu expands from six clear options to forty equally weighted items and users take longer to choose.", answer: "Hick's Law", backInfo: "Choice time generally increases with more and more complex alternatives. The implication is not “always show fewer items”; grouping, defaults and progressive disclosure can reduce decision complexity." },
  { id: "ix-11", category: "11", group: "design", level: "foundation", mode: "recall", frontQuestion: "Which principle says users spend most of their time in other products and bring those learned conventions with them?", frontScenario: "A custom close icon behaves differently from the convention users know across desktop apps.", answer: "Jakob's Law", backInfo: "Users form expectations from other products, so familiar conventions can reduce learning. Break conventions deliberately only when the benefit outweighs the added learning cost." },
  { id: "ix-12", category: "11", group: "design", level: "foundation", mode: "application", frontQuestion: "What pattern reveals complexity gradually so users first see what is necessary for the current task?", frontScenario: "An advanced analytics screen initially shows core filters while specialist controls remain available on demand.", answer: "Progressive Disclosure", backInfo: "Showing essential information/actions first and revealing advanced complexity when needed. It reduces initial cognitive load without permanently removing power features." },
  { id: "ix-13", category: "11", group: "design", level: "foundation", mode: "application", frontQuestion: "Which design principle tries to stop predictable mistakes before they happen rather than relying only on error messages afterward?", frontScenario: "The product prevents booking an end date earlier than the start date instead of accepting it and failing later.", answer: "Error Prevention", backInfo: "Design choices that reduce the chance of mistakes through constraints, sensible defaults, previews and clear choices. Prevention is usually better than recovery when errors are predictable." },
  { id: "ix-14", category: "11", group: "design", level: "practice", mode: "application", frontQuestion: "Which design principle lets users recover easily from mistakes through actions such as undo, restore or reversible confirmation?", frontScenario: "A user accidentally deletes a board and immediately needs a safe way to reverse the action.", answer: "Forgiving Design", backInfo: "Interfaces should support recovery from ordinary human error through reversibility, undo, autosave, trash states or clear recovery paths where feasible." },
  { id: "ix-15", category: "11", group: "design", level: "practice", mode: "recall", frontQuestion: "What interaction style lets users act on visible objects directly through actions such as dragging, resizing or moving?", frontScenario: "A design canvas allows an object to be grabbed and resized rather than edited only through a command form.", answer: "Direct Manipulation", backInfo: "Interaction with visible objects using immediate actions and feedback. It can feel intuitive, but equivalent non-drag interactions may be needed for accessibility." },
  { id: "ix-16", category: "11", group: "design", level: "advanced", mode: "distinction", frontQuestion: "What is a persistent interaction condition in which the same user action has different effects until the condition changes?", frontScenario: "Pressing a key edits text in one state but performs keyboard shortcuts in another.", answer: "Mode", backInfo: "System state that changes the interpretation of user actions. Hidden or poorly signaled modes cause mode errors; visible mode indicators and easy exits reduce risk." },
  { id: "ix-17", category: "11", group: "design", level: "foundation", mode: "recall", frontQuestion: "What describes the current condition of a component or system, such as loading, selected, disabled, empty or error?", frontScenario: "A button can be default, hovered, focused, pressed, loading, disabled or successful.", answer: "State", backInfo: "Current condition that determines presentation and behavior. Explicit state design prevents missing edge cases and inconsistent feedback." },
  { id: "ix-18", category: "11", group: "design", level: "foundation", mode: "application", frontQuestion: "What UI state appears when there is no content yet and should explain what the area is for or what to do next?", frontScenario: "A new project has no tasks, so a blank white panel would leave the user unsure how to begin.", answer: "Empty State", backInfo: "Intentional design for absence of content. Useful empty states orient the user, explain why the area is empty and offer an appropriate next action when one exists." },
  { id: "ui-01", category: "12", group: "design", level: "foundation", mode: "recall", frontQuestion: "What principle uses size, weight, placement, color and spacing to communicate what should be noticed first, second and third?", frontScenario: "A dashboard contains all the right information but every element competes equally for attention.", answer: "Visual Hierarchy", backInfo: "Visual ordering of importance that guides attention and scanning. It should reflect task priority, not simply make the most decorative element largest." },
  { id: "ui-02", category: "12", group: "design", level: "foundation", mode: "recall", frontQuestion: "What principle creates meaningful visual difference so elements, priorities or states are easier to distinguish?", frontScenario: "Primary and secondary actions look almost identical, so users hesitate.", answer: "Contrast", backInfo: "Difference in visual properties such as size, weight, luminance, shape or spacing. Contrast supports hierarchy and differentiation; color contrast also has accessibility requirements." },
  { id: "ui-03", category: "12", group: "design", level: "foundation", mode: "application", frontQuestion: "Which Gestalt principle says elements placed near each other are perceived as belonging together?", frontScenario: "Labels sit closer to the wrong inputs than to the fields they describe.", answer: "Proximity", backInfo: "Spatial closeness implies grouping. Use spacing intentionally so related items form clear groups and unrelated items are separated." },
  { id: "ui-04", category: "12", group: "design", level: "foundation", mode: "recall", frontQuestion: "What principle creates visual order by placing elements along shared edges, baselines or axes?", frontScenario: "Cards use slightly different left edges and text baselines, making the layout feel unstable.", answer: "Alignment", backInfo: "Consistent positioning along shared visual lines. Good alignment creates relationships and reduces visual noise even without visible grid lines." },
  { id: "ui-05", category: "12", group: "design", level: "foundation", mode: "recall", frontQuestion: "What principle creates coherence by deliberately reusing visual patterns such as styles, shapes and spacing?", frontScenario: "Every settings section invents a different title style and divider treatment.", answer: "Repetition", backInfo: "Reuse of visual decisions to create rhythm, consistency and learnability. Repetition should be systematic rather than accidental duplication." },
  { id: "ui-06", category: "12", group: "design", level: "foundation", mode: "recall", frontQuestion: "What do you call intentionally unused space that separates groups and gives content room to breathe?", frontScenario: "A dense pricing page becomes much easier to scan after sections and labels receive clearer spacing.", answer: "Whitespace", backInfo: "Empty/negative space used to establish grouping, hierarchy and readability. It is functional layout space, not “wasted” space." },
  { id: "ui-07", category: "12", group: "design", level: "foundation", mode: "recall", frontQuestion: "What structural system uses columns, rows and gutters to organize layout consistently?", frontScenario: "Different pages need to align content even though their modules vary.", answer: "Grid", backInfo: "Layout framework for consistent alignment and proportional structure. A grid guides composition but does not require every element to occupy identical modules." },
  { id: "ui-08", category: "12", group: "design", level: "practice", mode: "recall", frontQuestion: "What system uses a limited, repeatable set of spacing increments instead of arbitrary gaps everywhere?", frontScenario: "A product contains 13px, 17px, 19px and 23px gaps that are visually almost the same but hard to maintain.", answer: "Spacing Scale", backInfo: "Defined set of spacing values used consistently across layouts and components. A scale improves rhythm and maintainability while still allowing documented exceptions." },
  { id: "ui-09", category: "12", group: "design", level: "foundation", mode: "recall", frontQuestion: "What typographic principle differentiates headings, body, labels and supporting text according to information importance?", frontScenario: "A long settings page uses the same size and weight for every line of text.", answer: "Typographic Hierarchy", backInfo: "Systematic use of type size, weight, spacing and style to communicate information levels. Hierarchy should support scan patterns and semantic structure." },
  { id: "ui-10", category: "12", group: "design", level: "practice", mode: "recall", frontQuestion: "What predefined set of font sizes provides consistent typographic steps across a product?", frontScenario: "Designers keep creating near-duplicate font sizes for headings and labels.", answer: "Type Scale", backInfo: "Controlled set of text sizes used across semantic roles. It improves consistency; the ratio can be modular or custom and should serve the interface rather than a mathematical rule." },
  { id: "ui-11", category: "12", group: "design", level: "foundation", mode: "recall", frontQuestion: "What typography property controls the vertical distance between lines of text?", frontScenario: "Body copy feels cramped even though the font size is readable.", answer: "Line Height — Leading", backInfo: "Vertical spacing between text baselines/line boxes. Appropriate line height improves readability and depends on font, size, line length and context." },
  { id: "ui-12", category: "12", group: "design", level: "practice", mode: "application", frontQuestion: "What typography consideration limits how wide a text column becomes so long-form reading does not require excessive eye movement?", frontScenario: "On a desktop article page, paragraphs stretch almost the full width of a 1600px screen.", answer: "Line Length", backInfo: "Width of a line of text, often discussed in characters per line. Comfortable ranges depend on typography and context; avoid treating one character count as an absolute law." },
  { id: "ui-13", category: "12", group: "design", level: "foundation", mode: "recall", frontQuestion: "What approach adapts layout and components to different viewport sizes and device capabilities rather than designing one fixed canvas?", frontScenario: "The same product must remain usable on phones, tablets and large desktop screens.", answer: "Responsive Design", backInfo: "Designing interfaces that adapt to available space and conditions using flexible layout, media/container queries and component behavior. It is more than shrinking a desktop screen." },
  { id: "ui-14", category: "12", group: "design", level: "foundation", mode: "distinction", frontQuestion: "What is a width or condition at which a responsive layout intentionally changes behavior or structure?", frontScenario: "A two-column settings layout becomes a single column when there is no longer enough room for both.", answer: "Breakpoint", backInfo: "Threshold at which responsive styles or layout rules change. Breakpoints should be driven by content/component needs rather than only by named device models." },
  { id: "ui-15", category: "12", group: "design", level: "practice", mode: "recall", frontQuestion: "What property describes how much information and interaction is packed into a given area of interface?", frontScenario: "A professional trading tool may need compact tables, while a first-time consumer flow benefits from more breathing room.", answer: "UI Density", backInfo: "Amount of information and controls presented per area. Appropriate density depends on task frequency, expertise, device and error cost; “more whitespace” is not universally better." },
  { id: "ui-16", category: "12", group: "design", level: "practice", mode: "recall", frontQuestion: "What system assigns colors by functional meaning such as background, text, accent, success, warning and danger rather than by arbitrary hex values?", frontScenario: "A redesign must support light and dark themes without components hardcoding “blue-500” as text color.", answer: "Semantic Color Roles", backInfo: "Colors named and applied by purpose rather than raw value. Semantic roles improve theming, accessibility management and design-system consistency." },
  { id: "ds-01", category: "13", group: "design", level: "foundation", mode: "recall", frontQuestion: "What is the shared system of reusable design decisions, components, guidance and governance used to build a product consistently at scale?", frontScenario: "Five squads keep rebuilding buttons, forms and patterns differently, creating design and code drift.", answer: "Design System", backInfo: "A connected set of reusable foundations, components, patterns, documentation and operating practices. It is more than a UI kit because governance, maintenance and adoption are part of the system." },
  { id: "ds-02", category: "13", group: "design", level: "foundation", mode: "recall", frontQuestion: "What named value stores a reusable design decision such as a color, spacing, typography or duration value independently of one component?", frontScenario: "Instead of hardcoding `#111111` in dozens of places, teams reference a shared named value.", answer: "Design Token", backInfo: "A named representation of a design decision that can be shared across tools and platforms. Modern token systems can include type, value, description and references/aliases." },
  { id: "ds-03", category: "13", group: "design", level: "practice", mode: "distinction", frontQuestion: "What kind of token represents a raw foundational value without yet expressing its UI purpose?", frontScenario: "The system stores a palette value such as `blue-600` that other tokens may reference.", answer: "Primitive / Reference Token", backInfo: "Foundational token representing a raw reusable value such as a palette color or spacing step. It is usually not the preferred token for direct component usage when semantic roles are available." },
  { id: "ds-04", category: "13", group: "design", level: "practice", mode: "distinction", frontQuestion: "What kind of token is named by purpose, such as `text-primary` or `surface-danger`, so the underlying value can change by theme?", frontScenario: "Dark mode needs the same “primary text” role to resolve to a different color than light mode.", answer: "Semantic Token", backInfo: "Token whose name expresses design intent or usage rather than raw value. Semantic tokens support theming, consistency and clearer cross-functional vocabulary." },
  { id: "ds-05", category: "13", group: "design", level: "advanced", mode: "recall", frontQuestion: "What token mechanism lets one token's value reference another token instead of duplicating the raw value?", frontScenario: "`text-primary` should follow the current neutral foreground token rather than copy its color manually.", answer: "Token Alias / Reference", backInfo: "A token value that references another token. Aliasing creates relationships between layers of the token system and makes theme/value changes propagate consistently." },
  { id: "ds-06", category: "13", group: "design", level: "practice", mode: "recall", frontQuestion: "What system capability lets the same semantic design decisions resolve differently for contexts such as light, dark or high-contrast themes?", frontScenario: "`surface-default` needs one value in light mode and another in dark mode while components keep the same semantic reference.", answer: "Mode / Theme", backInfo: "Contextual set of token values or component styling rules for a visual theme or mode. Components should depend on semantic intent rather than hardcoded theme-specific values." },
  { id: "ds-07", category: "13", group: "design", level: "foundation", mode: "recall", frontQuestion: "What reusable UI building block packages structure, styling and behavior for repeated use?", frontScenario: "Buttons, checkboxes and dialogs should not be redrawn and reimplemented from scratch on every screen.", answer: "Component", backInfo: "Reusable interface building block with defined structure, states and behavior. A component should have a clear purpose and documented usage, not exist only because elements look similar." },
  { id: "ds-08", category: "13", group: "design", level: "foundation", mode: "recall", frontQuestion: "What represents a legitimate variation of the same component, such as size, hierarchy or state, without creating a separate unrelated component?", frontScenario: "A button can be primary or secondary and small or large while keeping the same core component behavior.", answer: "Variant", backInfo: "Defined variation within a component family. Variants should represent meaningful supported differences rather than every accidental visual combination." },
  { id: "ds-09", category: "13", group: "design", level: "advanced", mode: "recall", frontQuestion: "What describes the documented properties, states, slots and behaviors through which teams configure and use a component?", frontScenario: "Designers and developers need the same understanding of what a dialog allows: size, title, actions, dismiss behavior and states.", answer: "Component API", backInfo: "Contract describing configurable inputs and supported behavior of a component. A clear API reduces one-off overrides and improves design–code alignment." },
  { id: "ds-10", category: "13", group: "design", level: "practice", mode: "distinction", frontQuestion: "What reusable solution combines multiple components and behavior to solve a recurring user problem rather than defining one atomic control?", frontScenario: "Search with filters, empty results and pagination repeats across several products.", answer: "UI Pattern", backInfo: "Reusable interaction/composition solution for a recurring problem. Patterns are larger and more contextual than individual components." },
  { id: "ds-11", category: "13", group: "design", level: "practice", mode: "recall", frontQuestion: "What operating model defines who makes design-system decisions, how standards are maintained and how teams adopt them?", frontScenario: "Everyone can edit the library, but nobody owns quality, accessibility, releases or breaking changes.", answer: "Design System Governance", backInfo: "Roles, decision processes and maintenance rules that keep a design system coherent over time. Governance should enable contribution without making ownership ambiguous." },
  { id: "ds-12", category: "13", group: "design", level: "practice", mode: "application", frontQuestion: "What process lets product teams propose, review and add reusable improvements to the shared system instead of keeping local forks?", frontScenario: "A squad builds a new date-range pattern that could benefit six other teams.", answer: "Contribution Model", backInfo: "Defined workflow for proposing, evaluating, building, documenting and releasing additions to the design system. It balances central quality with distributed expertise." },
  { id: "ds-13", category: "13", group: "design", level: "practice", mode: "recall", frontQuestion: "What practice communicates compatible, additive and breaking changes across design-system releases?", frontScenario: "Renaming a component property could break dozens of product implementations.", answer: "Versioning", backInfo: "Managing identifiable releases so consumers understand change and compatibility. Semantic versioning concepts can help in code, but design assets also need clear release communication." },
  { id: "ds-14", category: "13", group: "design", level: "practice", mode: "recall", frontQuestion: "What lifecycle state indicates that a component, token or API should no longer be used and has a preferred replacement or migration path?", frontScenario: "An old input component still exists in products but should be replaced by the accessible new version.", answer: "Deprecation", backInfo: "Marking an API/component/token as obsolete while communicating why, what replaces it and how/when to migrate. Silent deletion creates avoidable breakage." },
  { id: "ds-15", category: "13", group: "design", level: "advanced", mode: "application", frontQuestion: "What condition means the documented design component and the production code component represent the same supported structure, properties and states?", frontScenario: "Figma shows five button variants while code supports eight different behaviors and naming conventions.", answer: "Design–Code Parity", backInfo: "Alignment between design assets and coded components so teams share one conceptual contract. Perfect visual identity alone is not enough; props, states and behavior should also align where applicable." },
  { id: "ds-16", category: "13", group: "design", level: "advanced", mode: "application", frontQuestion: "What automated testing approach compares rendered UI against expected visuals to detect unintended styling or layout changes?", frontScenario: "A dependency update silently changes spacing across every form field.", answer: "Visual Regression Testing", backInfo: "Automated comparison of rendered interface snapshots or images to detect unexpected visual changes. It complements functional and accessibility tests rather than replacing them." },
  { id: "a11y-01", category: "14", group: "design", level: "foundation", mode: "recall", frontQuestion: "What design approach deliberately considers a broad range of abilities, contexts and forms of exclusion instead of designing only for an assumed average user?", frontScenario: "A team considers permanent, temporary and situational limitations when designing identity verification.", answer: "Inclusive Design", backInfo: "Designing with diverse people and contexts to reduce exclusion and expand usable participation. Accessibility standards are a critical part of this work but inclusive design is broader than compliance alone." },
  { id: "a11y-02", category: "14", group: "design", level: "foundation", mode: "recall", frontQuestion: "Which four principles organize WCAG accessibility requirements?", frontScenario: "The team needs the top-level model behind web accessibility rather than memorizing isolated criteria.", answer: "POUR — Perceivable, Operable, Understandable, Robust", backInfo: "WCAG's four principles: content/interface must be perceivable, operable, understandable and robust. Success criteria sit under these principles." },
  { id: "a11y-03", category: "14", group: "design", level: "foundation", mode: "application", frontQuestion: "What should developers prefer before adding ARIA because native elements already carry useful meaning and behavior for assistive technology?", frontScenario: "A clickable control was built from a styled `div`, requiring extra work for keyboard and screen-reader behavior.", answer: "Semantic HTML", backInfo: "Using native elements according to their meaning, such as buttons, headings, lists and form controls. Native semantics usually provide stronger accessibility and interaction behavior than generic elements recreated with scripts." },
  { id: "a11y-04", category: "14", group: "design", level: "practice", mode: "recall", frontQuestion: "What programmatically exposed text tells assistive technology what an interactive control or element is called?", frontScenario: "An icon-only close button is visible but a screen reader announces only “button.”", answer: "Accessible Name", backInfo: "The name exposed to assistive technologies for an element, derived from visible text, labels, `alt`, `aria-label` or other name-calculation sources. It should match the control's purpose." },
  { id: "a11y-05", category: "14", group: "design", level: "foundation", mode: "application", frontQuestion: "What capability ensures all essential functionality can be reached and operated without requiring a mouse?", frontScenario: "A user navigates forms and dialogs entirely with a keyboard or switch device.", answer: "Keyboard Accessibility", backInfo: "Interactive functionality should be operable through keyboard-compatible input where applicable. Avoid keyboard traps and ensure custom widgets implement expected keyboard behavior." },
  { id: "a11y-06", category: "14", group: "design", level: "foundation", mode: "recall", frontQuestion: "What visual treatment lets keyboard users see which interactive element currently has focus?", frontScenario: "Tabbing moves through buttons but the design removed the browser outline and provides no replacement.", answer: "Visible Focus Indicator", backInfo: "Perceivable styling that shows keyboard focus. Do not remove focus indication without providing an accessible alternative with sufficient visibility." },
  { id: "a11y-07", category: "14", group: "design", level: "practice", mode: "application", frontQuestion: "What requirement ensures keyboard focus moves through controls in an order that preserves meaning and operability?", frontScenario: "A visually reordered checkout causes Tab to jump from payment back to shipping and then to the header.", answer: "Logical Focus Order", backInfo: "Focus sequence should preserve the intended meaning and operation of the interface. Visual CSS reordering must not create a confusing keyboard sequence." },
  { id: "a11y-08", category: "14", group: "design", level: "foundation", mode: "recall", frontQuestion: "What WCAG measure checks whether text is visually distinguishable enough from its background?", frontScenario: "Light gray body text on white looks elegant but is difficult for many users to read.", answer: "Text Contrast Ratio", backInfo: "WCAG 2.2 AA generally requires at least 4.5:1 for normal text and 3:1 for large text, with defined exceptions. Contrast is based on relative luminance, not subjective appearance." },
  { id: "a11y-09", category: "14", group: "design", level: "practice", mode: "distinction", frontQuestion: "What WCAG requirement applies contrast to important UI component boundaries and graphical objects, not just text?", frontScenario: "An input border and focus control are so faint that users cannot perceive where interaction is possible.", answer: "Non-text Contrast", backInfo: "WCAG criterion requiring sufficient contrast for visual information needed to identify UI components and graphical objects, generally 3:1 against adjacent colors where the criterion applies." },
  { id: "a11y-10", category: "14", group: "design", level: "practice", mode: "recall", frontQuestion: "What WCAG 2.2 criterion sets a minimum pointer target size or sufficient spacing for small targets?", frontScenario: "Tiny icon buttons are packed closely together on mobile, making accidental activation likely.", answer: "Target Size (Minimum) — WCAG 2.5.8", backInfo: "WCAG 2.2 AA requires pointer targets to be at least 24 × 24 CSS pixels or meet specified spacing/other exceptions. Larger targets may still be preferable for usability." },
  { id: "a11y-11", category: "14", group: "design", level: "practice", mode: "application", frontQuestion: "What WCAG 2.2 requirement says functionality based on dragging should also be possible with a simple pointer action unless dragging is essential?", frontScenario: "Reordering items works only by click-and-drag, which some users cannot perform accurately.", answer: "Dragging Movements — WCAG 2.5.7", backInfo: "If functionality uses dragging, provide a single-pointer alternative such as buttons or menus unless dragging is essential or controlled by the user agent." },
  { id: "a11y-12", category: "14", group: "design", level: "foundation", mode: "application", frontQuestion: "What text alternative should communicate the purpose or relevant content of a meaningful image to someone who cannot see it?", frontScenario: "A chart image conveys quarterly sales but has no equivalent description.", answer: "Alt Text — Text Alternative", backInfo: "Concise alternative describing the relevant purpose/content of non-text content. Decorative images should usually be ignored by assistive technology rather than described needlessly." },
  { id: "a11y-13", category: "14", group: "design", level: "foundation", mode: "application", frontQuestion: "What synchronized text alternative makes spoken audio in video available to people who cannot hear it?", frontScenario: "A product tutorial relies on narration to explain steps that are not visible in the video itself.", answer: "Captions", backInfo: "Synchronized text representing speech and relevant non-speech audio in video. Prerecorded multimedia accessibility may also require transcripts or audio description depending on content and criteria." },
  { id: "a11y-14", category: "14", group: "design", level: "practice", mode: "application", frontQuestion: "What user preference should animations respect when motion could trigger discomfort or make the interface harder to use?", frontScenario: "A parallax-heavy onboarding experience makes some users dizzy.", answer: "Reduced Motion", backInfo: "Support preferences such as `prefers-reduced-motion` and remove/reduce non-essential motion. Essential state changes should remain understandable without relying on dramatic animation." },
  { id: "a11y-15", category: "14", group: "design", level: "practice", mode: "distinction", frontQuestion: "What specification adds accessibility semantics to web content when native HTML alone cannot express a custom widget correctly?", frontScenario: "A custom tree control needs programmatic roles, states and relationships for assistive technology.", answer: "ARIA — Accessible Rich Internet Applications", backInfo: "WAI-ARIA defines roles, states and properties for accessibility semantics. No ARIA is better than bad ARIA; use native HTML whenever it already provides the correct semantics and behavior." },
  { id: "a11y-16", category: "14", group: "design", level: "advanced", mode: "application", frontQuestion: "What WCAG 2.2 principle prevents login from depending on cognitive tests such as memorizing or transcribing information when accessible alternatives can be provided?", frontScenario: "A login requires users to remember a password and manually retype a one-time code with no password-manager or copy/paste support.", answer: "Accessible Authentication — WCAG 3.3.8", backInfo: "WCAG 2.2 AA limits cognitive-function tests in authentication unless an allowed alternative/mechanism is provided. Support mechanisms such as password managers and copy/paste rather than blocking them unnecessarily." },
  { id: "a11y-17", category: "14", group: "design", level: "practice", mode: "application", frontQuestion: "What WCAG 2.2 requirement says information already entered in the same process should not be requested again unnecessarily?", frontScenario: "A multi-step checkout asks the user to retype the same address on two consecutive screens.", answer: "Redundant Entry — WCAG 3.3.7", backInfo: "Previously entered information required again in the same process should be auto-populated or selectable, with defined exceptions such as essential/security reasons." },
  { id: "a11y-18", category: "14", group: "design", level: "practice", mode: "application", frontQuestion: "What accessibility behavior lets content remain usable when users zoom or the viewport becomes narrow without forcing two-dimensional scrolling for ordinary text content?", frontScenario: "At 400% zoom, labels overlap and users must pan horizontally for every line.", answer: "Reflow", backInfo: "WCAG reflow requirements support reading and operation at narrow equivalent viewport widths without loss of information/functionality, except for content that genuinely requires two-dimensional layout." },
  { id: "dl-01", category: "15", group: "delivery-business", level: "foundation", mode: "recall", frontQuestion: "In Scrum, what is the ordered, evolving list of work needed to improve the product?", frontScenario: "New learning continually changes what the team may need to build or fix next.", answer: "Product Backlog", backInfo: "Emergent ordered list of what is needed to improve the product and the single source of work undertaken by the Scrum Team. It evolves as the team learns." },
  { id: "dl-02", category: "15", group: "delivery-business", level: "foundation", mode: "distinction", frontQuestion: "In Scrum, what plan contains the Sprint Goal, selected Product Backlog items and the actionable plan for delivering them?", frontScenario: "During a Sprint, developers update their plan as they learn more about the work.", answer: "Sprint Backlog", backInfo: "Plan by and for the Developers containing the Sprint Goal, selected backlog items and delivery plan. It is updated throughout the Sprint." },
  { id: "dl-03", category: "15", group: "delivery-business", level: "foundation", mode: "recall", frontQuestion: "In Scrum, what fixed-length container of one month or less turns ideas into value and contains the other Scrum events?", frontScenario: "A team works in repeating two-week cycles that include planning, daily work, review and retrospective.", answer: "Sprint", backInfo: "Fixed-length Scrum event of one month or less. A new Sprint starts immediately after the previous one; scope may be clarified while the Sprint Goal is protected." },
  { id: "dl-04", category: "15", group: "delivery-business", level: "foundation", mode: "recall", frontQuestion: "What single objective gives a Scrum Sprint coherence and focus while allowing flexibility in the exact work?", frontScenario: "Several backlog items change, but the team still needs one reason why the Sprint matters.", answer: "Sprint Goal", backInfo: "The single objective for the Sprint. It provides focus and flexibility: teams may renegotiate scope without undermining the goal." },
  { id: "dl-05", category: "15", group: "delivery-business", level: "foundation", mode: "recall", frontQuestion: "What shared quality commitment defines what must be true for completed work to count as done?", frontScenario: "One team calls a feature “done” before accessibility testing while another includes release-ready quality checks.", answer: "Definition of Done", backInfo: "Formal description of the state of the Increment when it meets required quality measures. It creates shared transparency about completion." },
  { id: "dl-06", category: "15", group: "delivery-business", level: "practice", mode: "recall", frontQuestion: "What ongoing activity breaks down and further defines backlog items so future work becomes clearer and appropriately sized?", frontScenario: "A large vague request is discussed, split and clarified before the team considers selecting it for a Sprint.", answer: "Product Backlog Refinement", backInfo: "Ongoing activity of breaking down and further defining Product Backlog items, adding details such as description, order and size. It is not a formal Scrum event." },
  { id: "dl-07", category: "15", group: "delivery-business", level: "foundation", mode: "distinction", frontQuestion: "Which Scrum event inspects the Sprint's outcome with stakeholders and adapts what to do next?", frontScenario: "The team demonstrates working outcomes and discusses changed market conditions with stakeholders.", answer: "Sprint Review", backInfo: "Working session near the end of the Sprint to inspect results and adapt the Product Backlog based on what changed. It is not merely a presentation/demo ceremony." },
  { id: "dl-08", category: "15", group: "delivery-business", level: "foundation", mode: "distinction", frontQuestion: "Which Scrum event focuses on improving the team's quality and effectiveness rather than reviewing the product outcome?", frontScenario: "After delivery, the team discusses collaboration, process, tools and how to work better next Sprint.", answer: "Sprint Retrospective", backInfo: "Event for inspecting how the Sprint went and planning improvements to quality and effectiveness. It focuses on the team's way of working." },
  { id: "dl-09", category: "15", group: "delivery-business", level: "foundation", mode: "recall", frontQuestion: "What lightweight requirement format commonly states “As a…, I want…, so that…” to express user value?", frontScenario: "A backlog item needs to communicate who needs something and why without becoming a full design specification.", answer: "User Story", backInfo: "Short agile requirement format intended to trigger conversation about user need and value. The template is optional; a user story is not a substitute for shared understanding or acceptance criteria." },
  { id: "dl-10", category: "15", group: "delivery-business", level: "foundation", mode: "recall", frontQuestion: "What conditions define how the team will determine whether a specific backlog item or feature behavior is acceptable?", frontScenario: "Designers and engineers disagree on whether an empty search result counts as complete behavior.", answer: "Acceptance Criteria", backInfo: "Testable conditions a specific item must satisfy. They clarify expected behavior and edge cases; unlike Definition of Done, they are item-specific." },
  { id: "dl-11", category: "15", group: "delivery-business", level: "foundation", mode: "recall", frontQuestion: "What flow-based method visualizes work and manages it continuously rather than requiring fixed Sprints?", frontScenario: "A support/product team handles a steady stream of work with changing priorities and wants to optimize flow.", answer: "Kanban", backInfo: "Method for visualizing and managing workflow, limiting work in progress and improving flow. It can coexist with other agile practices." },
  { id: "dl-12", category: "15", group: "delivery-business", level: "practice", mode: "application", frontQuestion: "What policy limits how many items may be actively worked on at once so the team finishes more instead of starting everything?", frontScenario: "Ten tasks are “in progress,” blockers accumulate and almost nothing reaches done.", answer: "WIP Limit — Work in Progress Limit", backInfo: "Explicit cap on concurrent work in a workflow state. WIP limits expose bottlenecks, reduce multitasking and support smoother flow." },
  { id: "dl-13", category: "15", group: "delivery-business", level: "practice", mode: "distinction", frontQuestion: "Which flow metric measures elapsed time from when work actually starts until it is finished?", frontScenario: "An item waits in backlog for a month, then takes four days from development start to completion.", answer: "Cycle Time", backInfo: "Elapsed time from work start to completion according to the workflow definition. It focuses on active delivery flow and differs from total lead time." },
  { id: "dl-14", category: "15", group: "delivery-business", level: "practice", mode: "distinction", frontQuestion: "Which flow metric measures total elapsed time from request/commitment to delivery, including waiting before active work begins?", frontScenario: "A customer request waits three weeks before implementation and then takes four days to finish.", answer: "Lead Time", backInfo: "Time from a defined request/commitment point until delivery. It includes queue/waiting time and therefore reflects the customer's broader wait more than cycle time." },
  { id: "biz-01", category: "16", group: "delivery-business", level: "foundation", mode: "recall", frontQuestion: "What concise document aligns everyone on the problem, goals, audience, constraints and context before work begins?", frontScenario: "A client says “redesign the dashboard,” but the team needs to understand why, for whom and under what constraints.", answer: "Project Brief", backInfo: "Shared framing of the project context, problem, objectives, audience, constraints and relevant background. A brief should guide decisions without pretending unknowns are already resolved." },
  { id: "biz-02", category: "16", group: "delivery-business", level: "foundation", mode: "recall", frontQuestion: "What defines what work is included and excluded from an engagement?", frontScenario: "A website project quietly expands from five templates to an app, design system and content migration.", answer: "Scope", backInfo: "Explicit boundary of work, responsibilities and included outcomes. Clear exclusions and assumptions are as important as the included work for preventing uncontrolled expansion." },
  { id: "biz-03", category: "16", group: "delivery-business", level: "foundation", mode: "distinction", frontQuestion: "What is a concrete output that a freelancer, agency or team commits to provide?", frontScenario: "The engagement includes a research report, prototype and design-system specification.", answer: "Deliverable", backInfo: "Tangible agreed output of the work. Deliverables should not be confused with the business outcome they are intended to support." },
  { id: "biz-04", category: "16", group: "delivery-business", level: "foundation", mode: "recall", frontQuestion: "What document explains the recommended approach, value, scope, timing and commercial terms before a client awards the work?", frontScenario: "A consultant responds to a prospective client's need with a tailored plan and price.", answer: "Proposal", backInfo: "Persuasive commercial document presenting understanding of the problem, recommended approach, scope and terms. It precedes or accompanies a formal contract/SOW depending on the engagement." },
  { id: "biz-05", category: "16", group: "delivery-business", level: "practice", mode: "recall", frontQuestion: "What formal project document specifies scope, deliverables, responsibilities, timeline, assumptions and acceptance/commercial terms?", frontScenario: "Both parties need a contract attachment that makes the engagement boundaries operationally clear.", answer: "SOW — Statement of Work", backInfo: "Detailed agreement describing the work to be performed and how it will be governed. Exact legal role varies by contract structure and jurisdiction." },
  { id: "biz-06", category: "16", group: "delivery-business", level: "foundation", mode: "distinction", frontQuestion: "What pricing model charges one agreed amount for a defined scope rather than billing each hour worked?", frontScenario: "A client buys a clearly bounded research-and-design package for €12,000.", answer: "Fixed Fee", backInfo: "Price agreed for a defined scope/output. The supplier takes more delivery-efficiency risk, so assumptions, change control and scope clarity matter." },
  { id: "biz-07", category: "16", group: "delivery-business", level: "foundation", mode: "distinction", frontQuestion: "What commercial model bills for the actual time spent and sometimes pass-through materials or expenses?", frontScenario: "The work is exploratory and requirements are expected to change weekly.", answer: "Time & Materials — T&M", backInfo: "Billing model based on actual labor time and agreed rates, plus eligible materials/expenses where applicable. It offers flexibility but requires transparent tracking and budget management." },
  { id: "biz-08", category: "16", group: "delivery-business", level: "practice", mode: "recall", frontQuestion: "What commercial arrangement reserves ongoing access or capacity for a recurring fee?", frontScenario: "A startup wants a designer available every month for product work rather than commissioning isolated projects.", answer: "Retainer", backInfo: "Recurring agreement that secures defined services, capacity or availability over time. Terms should state what is included, rollover rules and response expectations." },
  { id: "biz-09", category: "16", group: "delivery-business", level: "foundation", mode: "application", frontQuestion: "What formal mechanism handles requested work that falls outside the agreed scope and changes cost, timing or deliverables?", frontScenario: "Halfway through the project, the client asks to add a second platform and twenty new screens.", answer: "Change Request", backInfo: "Documented request to alter agreed scope, requirements, cost or schedule. A clear change-control process protects both client flexibility and delivery boundaries." },
  { id: "biz-10", category: "16", group: "delivery-business", level: "practice", mode: "application", frontQuestion: "What artifact identifies relevant people, their influence, interests and relationship to a project so engagement can be planned?", frontScenario: "A redesign stalls because the team spoke only with users and ignored legal, support and the executive sponsor.", answer: "Stakeholder Map", backInfo: "Structured view of people/groups affected by or influential over a project. It helps plan involvement, communication and decision pathways." },
  { id: "biz-11", category: "16", group: "delivery-business", level: "foundation", mode: "recall", frontQuestion: "What role has the authority to make or approve the final call when stakeholders disagree?", frontScenario: "Five stakeholders provide feedback, but nobody knows whose decision determines whether the design ships.", answer: "Decision Maker", backInfo: "Person or defined role with authority for the relevant decision. Clarifying decision rights prevents endless consensus-seeking and conflicting feedback." },
  { id: "biz-12", category: "16", group: "delivery-business", level: "foundation", mode: "recall", frontQuestion: "What is a significant checkpoint used to track progress or trigger review, payment or a project decision?", frontScenario: "Payment is due after research completion and again after prototype approval.", answer: "Milestone", backInfo: "Meaningful project checkpoint tied to progress, delivery, review or commercial terms. A milestone is not necessarily a task or exact calendar date by itself." },
  { id: "biz-13", category: "16", group: "delivery-business", level: "practice", mode: "recall", frontQuestion: "What contract concept defines who owns or may use the design, code, content and other work created during an engagement?", frontScenario: "A freelancer finishes a brand system, but the contract is unclear about whether the client receives ownership or only usage rights.", answer: "Intellectual Property Rights — IP Rights", backInfo: "Legal rights governing ownership, licensing and permitted use of created work. Assignment and licensing are different; exact terms should be explicit and jurisdiction-appropriate." },
  { id: "biz-14", category: "16", group: "delivery-business", level: "foundation", mode: "recall", frontQuestion: "What agreement restricts disclosure or use of specified confidential information shared during a business relationship?", frontScenario: "A startup shares unreleased product plans and customer data during vendor evaluation.", answer: "NDA — Non-Disclosure Agreement", backInfo: "Contract defining confidential information and obligations around its use/disclosure. An NDA does not replace appropriate data security, privacy terms or a full services contract." },
  { id: "tech-01", category: "17", group: "tech-ai", level: "foundation", mode: "recall", frontQuestion: "What part of a digital product runs in or presents the user-facing interface on the client side?", frontScenario: "A designer reports a broken modal layout that appears in the browser even though the server data is correct.", answer: "Frontend", backInfo: "User-facing application layer responsible for rendering interface and handling client-side interaction. The exact boundary varies across web, mobile and server-rendered architectures." },
  { id: "tech-02", category: "17", group: "tech-ai", level: "foundation", mode: "distinction", frontQuestion: "What part of a product typically handles server-side business logic, data access and services not directly rendered as UI?", frontScenario: "The interface sends a request to create an order, and server logic validates inventory and stores the transaction.", answer: "Backend", backInfo: "Server-side systems and services that implement business logic, data access and integrations. A backend may consist of one service or many distributed services." },
  { id: "tech-03", category: "17", group: "tech-ai", level: "foundation", mode: "recall", frontQuestion: "What defined interface lets one software system request data or actions from another?", frontScenario: "A mobile app needs a documented way to retrieve account data from the company's service.", answer: "API — Application Programming Interface", backInfo: "Contract for software interaction. APIs define available operations, inputs, outputs and behavior so systems can communicate without sharing internal implementation." },
  { id: "tech-04", category: "17", group: "tech-ai", level: "practice", mode: "distinction", frontQuestion: "What common web API style models resources and uses HTTP methods such as GET, POST, PATCH and DELETE?", frontScenario: "A product exposes `/users/123` and `/orders/456` endpoints over HTTP.", answer: "REST — Representational State Transfer", backInfo: "Architectural style commonly used for resource-oriented web APIs. Real “REST APIs” vary widely; the label should not be treated as a guarantee of one exact implementation." },
  { id: "tech-05", category: "17", group: "tech-ai", level: "practice", mode: "distinction", frontQuestion: "What API query language lets clients request exactly the fields they need through a typed schema, often from a single endpoint?", frontScenario: "A dashboard needs different combinations of nested customer data on different screens without many fixed REST responses.", answer: "GraphQL", backInfo: "Query language and runtime for APIs based on a typed schema. Clients specify requested fields; this flexibility also requires thoughtful authorization, performance and schema design." },
  { id: "tech-06", category: "17", group: "tech-ai", level: "foundation", mode: "recall", frontQuestion: "What specific API address or operation receives a request for a particular resource or capability?", frontScenario: "Engineering asks which URL the client should call to submit a support ticket.", answer: "Endpoint", backInfo: "Addressed API location/operation through which a client accesses a capability or resource. In some API styles, “operation” is more accurate than thinking only in URLs." },
  { id: "tech-07", category: "17", group: "tech-ai", level: "foundation", mode: "recall", frontQuestion: "What pair describes data sent to a service and the result returned by that service?", frontScenario: "The app sends an order payload and receives either the created order or an error.", answer: "Request / Response", backInfo: "A request asks a service to perform or return something; a response communicates the result, status and data. This pattern underlies common HTTP/API interactions." },
  { id: "tech-08", category: "17", group: "tech-ai", level: "foundation", mode: "recall", frontQuestion: "What three-digit HTTP value communicates the high-level result of a web request, such as success, client error or server error?", frontScenario: "The API returns `404` when an object does not exist and `500` when the server fails unexpectedly.", answer: "HTTP Status Code", backInfo: "Standard code indicating request outcome classes such as 2xx success, 4xx client-side/request conditions and 5xx server errors. The code should match the actual semantics of the result." },
  { id: "tech-09", category: "17", group: "tech-ai", level: "practice", mode: "application", frontQuestion: "What mechanism sends an HTTP notification to another system when an event occurs instead of making that system constantly poll for changes?", frontScenario: "A payment provider tells your backend immediately when a charge succeeds.", answer: "Webhook", backInfo: "Event-driven HTTP callback sent from one system to another. Consumers should handle verification, retries, duplication/idempotency and out-of-order delivery where relevant." },
  { id: "tech-10", category: "17", group: "tech-ai", level: "foundation", mode: "recall", frontQuestion: "What persistent system stores and organizes application data for later retrieval and update?", frontScenario: "Accounts, projects and permissions must survive after the user closes the app.", answer: "Database", backInfo: "System for persistent structured or semi-structured data storage and querying. Database choices involve trade-offs in consistency, querying, scale and operations." },
  { id: "tech-11", category: "17", group: "tech-ai", level: "practice", mode: "application", frontQuestion: "What temporary storage keeps frequently used data closer to where it is needed so repeated work or network access is reduced?", frontScenario: "A dashboard repeatedly requests the same expensive data and feels slow even though that data changes only every few minutes.", answer: "Cache", backInfo: "Temporary stored copy of data or computation used to improve speed and reduce load. Cache invalidation and staleness rules are essential because cached data can become outdated." },
  { id: "tech-12", category: "17", group: "tech-ai", level: "practice", mode: "recall", frontQuestion: "What distributed network serves static or cached content from locations closer to users to reduce delivery time and origin load?", frontScenario: "Users in Australia download the same images from a server located only in Europe and experience unnecessary delay.", answer: "CDN — Content Delivery Network", backInfo: "Distributed edge network that serves content closer to users. CDNs commonly improve latency, resilience and bandwidth efficiency for cacheable assets and web delivery." },
  { id: "tech-13", category: "17", group: "tech-ai", level: "foundation", mode: "recall", frontQuestion: "What term describes the delay between initiating an action/request and receiving the relevant response?", frontScenario: "An AI assistant eventually returns a good answer, but users wait eight seconds after pressing Send.", answer: "Latency", backInfo: "Time delay in a system interaction. Users perceive different parts of latency, so teams may track network, server, model and end-to-end response timings separately." },
  { id: "tech-14", category: "17", group: "tech-ai", level: "foundation", mode: "distinction", frontQuestion: "What security process verifies that a user or system is who it claims to be?", frontScenario: "A person signs in using passkey, password or another identity mechanism.", answer: "Authentication — AuthN", backInfo: "Verification of identity. Authentication answers “Who are you?” and is distinct from authorization, which decides what that identity may do." },
  { id: "tech-15", category: "17", group: "tech-ai", level: "foundation", mode: "distinction", frontQuestion: "What security process determines what an authenticated identity is allowed to access or change?", frontScenario: "Two employees can sign in, but only an admin may change billing settings.", answer: "Authorization — AuthZ", backInfo: "Rules determining permitted actions/resources for an identity. Authorization answers “What are you allowed to do?” and must be enforced on trusted server-side boundaries, not only hidden in UI." },
  { id: "tech-16", category: "17", group: "tech-ai", level: "foundation", mode: "recall", frontQuestion: "What architecture separates a requester/user-facing application from a service that processes requests and provides resources?", frontScenario: "A browser requests product data from a remote application service and renders the response.", answer: "Client–Server Model", backInfo: "Architecture where clients request services/resources from servers. Modern systems may add edge, peer, local and distributed layers, but the client–server distinction remains useful vocabulary." },
  { id: "ai-01", category: "18", group: "tech-ai", level: "foundation", mode: "recall", frontQuestion: "What type of model is trained on large amounts of language data to generate or transform text and often other modalities?", frontScenario: "A product can summarize documents, answer questions and generate structured text from instructions.", answer: "LLM — Large Language Model", backInfo: "A large learned model capable of language understanding/generation tasks. Modern products may use LLMs as one component inside a larger system with tools, retrieval, rules and evaluation." },
  { id: "ai-02", category: "18", group: "tech-ai", level: "foundation", mode: "recall", frontQuestion: "What is the small unit of text or other model input/output that model limits and usage costs are commonly measured in?", frontScenario: "A long document consumes far more model capacity than its visible character count alone suggests.", answer: "Token", backInfo: "Unit produced by a model's tokenizer and used to represent input/output. A token is not the same as a word; tokenization varies by model and language." },
  { id: "ai-03", category: "18", group: "tech-ai", level: "foundation", mode: "recall", frontQuestion: "What limit describes how much input, conversation history and often generated output a model can consider in one inference?", frontScenario: "A support assistant begins forgetting early parts of a very long conversation because too much material is included.", answer: "Context Window", backInfo: "Maximum token capacity available to a model for a request/conversation context under the model's rules. Large context does not guarantee equally strong attention to every included detail." },
  { id: "ai-04", category: "18", group: "tech-ai", level: "foundation", mode: "recall", frontQuestion: "What is the instruction and context given to a generative model to shape the task and desired output?", frontScenario: "A product provides role, constraints, user request and examples before asking the model to draft a result.", answer: "Prompt", backInfo: "Input instructions/context used to guide model behavior. In production systems, prompting is only one layer; tools, retrieval, schemas, permissions and evals often matter just as much." },
  { id: "ai-05", category: "18", group: "tech-ai", level: "practice", mode: "recall", frontQuestion: "What numeric vector representation lets semantically similar pieces of content be compared by meaning rather than exact words?", frontScenario: "Search should find “cancel my subscription” when the stored article says “terminate membership.”", answer: "Embedding", backInfo: "Learned vector representation of content used for semantic similarity, clustering, retrieval and related tasks. Embeddings are commonly indexed in vector-capable storage for retrieval." },
  { id: "ai-06", category: "18", group: "tech-ai", level: "practice", mode: "application", frontQuestion: "What architecture retrieves relevant external information and supplies it to a generative model at request time?", frontScenario: "An assistant must answer from current company documentation without retraining the base model every time a policy changes.", answer: "RAG — Retrieval-Augmented Generation", backInfo: "Retrieval step finds relevant external content and adds it to model context before generation. RAG can improve freshness and grounding, but retrieval quality and citation/evaluation still matter." },
  { id: "ai-07", category: "18", group: "tech-ai", level: "practice", mode: "distinction", frontQuestion: "What practice connects model output to verifiable source data, tools or retrieved evidence so answers are less dependent on unsupported model memory?", frontScenario: "A legal assistant must answer from the customer's approved policy corpus and show supporting references.", answer: "Grounding", backInfo: "Constraining or supporting generation with authoritative context or external evidence. Grounding reduces unsupported claims but does not guarantee factual correctness." },
  { id: "ai-08", category: "18", group: "tech-ai", level: "foundation", mode: "recall", frontQuestion: "What do you call a model output that presents unsupported or incorrect information as if it were valid?", frontScenario: "An assistant invents a policy clause that does not exist in any supplied document.", answer: "Hallucination", backInfo: "Generated content that is unsupported, fabricated or inconsistent with the relevant source/ground truth. Product design should manage the risk through grounding, tools, uncertainty handling and evals." },
  { id: "ai-09", category: "18", group: "tech-ai", level: "practice", mode: "application", frontQuestion: "What capability lets a model choose and invoke defined external functions or tools instead of only generating text?", frontScenario: "An assistant checks inventory, creates a calendar event and retrieves account data through approved functions.", answer: "Tool Use / Function Calling", backInfo: "Model capability to select structured tools/functions and provide arguments for external execution. Tools expand capability but require permissions, validation, error handling and clear user control." },
  { id: "ai-10", category: "18", group: "tech-ai", level: "practice", mode: "recall", frontQuestion: "What AI system can decide among steps, tools and intermediate actions in pursuit of a user goal rather than returning one fixed completion?", frontScenario: "A travel assistant searches options, compares them, checks constraints and performs approved actions across several steps.", answer: "Agent", backInfo: "AI system that can manage a goal through iterative reasoning/decision steps and tool use. Product teams must define permissions, stopping conditions, observability and human control." },
  { id: "ai-11", category: "18", group: "tech-ai", level: "advanced", mode: "distinction", frontQuestion: "What workflow allows an AI system to plan, act, observe results and continue across multiple steps instead of following a single predetermined sequence?", frontScenario: "The system retries a failed data lookup with another tool and adjusts its next step based on the result.", answer: "Agentic Workflow", backInfo: "Multi-step workflow where model-driven decisions influence which actions/tools occur next. “Agentic” does not mean unlimited autonomy; boundaries and approvals should be explicit." },
  { id: "ai-12", category: "18", group: "tech-ai", level: "practice", mode: "recall", frontQuestion: "What open protocol standardizes how AI applications connect to external tools, resources and contextual systems?", frontScenario: "The same company knowledge/search tool should be usable by multiple compatible AI clients without bespoke integration for each one.", answer: "MCP — Model Context Protocol", backInfo: "Open protocol for connecting AI applications with tools, resources and related context. By 2026 MCP is a major interoperability term; implementations still require security, authorization and trust boundaries." },
  { id: "ai-13", category: "18", group: "tech-ai", level: "practice", mode: "application", frontQuestion: "What output method constrains model responses to a defined machine-readable schema instead of hoping free-form text happens to parse?", frontScenario: "A workflow needs guaranteed fields such as `name`, `risk_level` and `recommended_action` for downstream software.", answer: "Structured Outputs", backInfo: "Model output constrained to a specified structure/schema, commonly JSON Schema. It improves reliability of shape and types but does not guarantee the semantic truth of values." },
  { id: "ai-14", category: "18", group: "tech-ai", level: "foundation", mode: "recall", frontQuestion: "What systematic tests measure whether an AI system performs acceptably on defined tasks and failure cases?", frontScenario: "A team changes the model and prompt and needs evidence that answer quality improved without increasing unsafe behavior.", answer: "Evals — Evaluations", backInfo: "Repeatable datasets, criteria and grading methods used to assess model/system behavior. Strong eval suites include representative success cases, edge cases and important failure modes." },
  { id: "ai-15", category: "18", group: "tech-ai", level: "practice", mode: "application", frontQuestion: "What workflow keeps a person responsible for review, approval or intervention at critical steps instead of allowing fully autonomous execution?", frontScenario: "AI drafts customer refunds, but a support agent must approve high-value cases before money moves.", answer: "Human in the Loop — HITL", backInfo: "System design where humans review, approve, correct or take over at defined points. Use it based on risk and accountability, not as a vague promise that “a human is somewhere involved.”" },
  { id: "ai-16", category: "18", group: "tech-ai", level: "advanced", mode: "recall", frontQuestion: "What attack tries to manipulate an AI system by placing malicious instructions in user input, retrieved content or external data?", frontScenario: "A webpage retrieved by an agent contains hidden text telling the model to ignore policy and expose secrets.", answer: "Prompt Injection", backInfo: "Adversarial instructions attempting to override intended behavior through model-visible content. Treat external content as untrusted data and enforce security outside the model, not only through prompts." },
  { id: "ai-17", category: "18", group: "tech-ai", level: "practice", mode: "recall", frontQuestion: "What broad term describes controls that constrain unsafe, disallowed or unwanted AI behavior before, during or after model execution?", frontScenario: "A healthcare assistant needs policy checks, restricted tools, moderation and escalation around model responses.", answer: "AI Guardrails", backInfo: "Layered controls such as permissions, validation, policy filters, tool restrictions, rate limits, monitoring and human escalation. Guardrails should be system-level defenses, not a single “be safe” prompt." },
  { id: "ai-18", category: "18", group: "tech-ai", level: "foundation", mode: "recall", frontQuestion: "What capability lets one model or AI system work across more than one data type such as text, images, audio or video?", frontScenario: "A support assistant reads a screenshot, listens to a voice note and replies in text.", answer: "Multimodal AI", backInfo: "AI capable of processing and/or producing multiple modalities. Product design must account for modality-specific latency, accessibility, privacy and error modes." },
  { id: "ai-19", category: "18", group: "tech-ai", level: "practice", mode: "distinction", frontQuestion: "What adaptation method further trains a pretrained model on curated examples or task/domain data rather than only changing the prompt at runtime?", frontScenario: "A company repeatedly needs a specialized response style and task behavior that prompting alone does not reliably provide.", answer: "Fine-tuning", backInfo: "Additional training that adapts a pretrained model using selected data. It can improve behavior for suitable tasks, but it is not the default solution for injecting frequently changing factual knowledge." },
  { id: "ai-20", category: "18", group: "tech-ai", level: "practice", mode: "recall", frontQuestion: "What do you call the runtime process of using a trained model to produce a prediction or generated output from new input?", frontScenario: "The model is already trained; every user request now consumes compute to generate a response.", answer: "Inference", backInfo: "Execution of a trained model on new input. Product teams often optimize inference for quality, latency, throughput and cost rather than treating “the model” as the entire product." },
];

export const cardById = Object.fromEntries(cards.map(c => [c.id, c])) as Record<string, TrainingCard>;
export const cardsByCategory = (cat: string) => cards.filter(c => c.category === cat);
export const cardsByGroup = (g: string) => cards.filter(c => c.group === g);

export const cardName = (id: string): string => cardById[id]?.answer ?? id;
